        rlwimi  addr, prefetch_data, 24, 25, 27         // addr[6:4] = prefetch_data[14:12]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwnm   data, data, base_disp, 0, 31            // data = rotl(data, base_disp) & 0xFFFFFFFF
        beql    cr6, bfins_mem_3_L2
        mtctr   addr
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        subfc   base_disp, immed_data, base_disp        // base_disp = base_disp - immed_data
        srw     data, data, immed_data
        slw.    immed_data, data, immed_data
        cntlzw  addr, data                              // addr = number of leading zero bits in data
        addco   zero, zero, zero                        // V=0, C=0
        add     base_disp, base_disp, addr
        bctr

// Reached from 8 dispatch table entries:
//     BFEXTS Dn{ofs:wid},Dn
bfexts:
        mtcrf   0x0F, prefetch_data                     // cr4..cr7 = prefetch_data[15:0]
        rlwinm  base_disp, prefetch_data, 26, 27, 31    // base_disp = prefetch_data[10:6]
        neg     immed_data, prefetch_data
        ori     addr, code_ptr, reg_access_base_disp_L1 - cb
        bltl    cr5, bfins_mem_3_L1
        rlwimi  addr, prefetch_data, 24, 25, 27         // addr[6:4] = prefetch_data[14:12]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwnm   data, data, base_disp, 0, 31            // data = rotl(data, base_disp) & 0xFFFFFFFF
        beql    cr6, bfins_mem_3_L2
        mtlr    addr
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        sraw.   base_disp, data, immed_data             // base_disp = data >> immed_data (arithmetic)
        addco   zero, zero, zero                        // V=0, C=0
        blr

// Reached from 27 dispatch table entries:
//     BFEXTU (d16,An){ofs:wid},Dn
//     BFEXTS (d16,An){ofs:wid},Dn
//     BFFFO (d16,An){ofs:wid},Dn
//     BFEXTU (d16,PC){ofs:wid},Dn
//     BFEXTS (d16,PC){ofs:wid},Dn
//     BFFFO (d16,PC){ofs:wid},Dn
bfextu_bfexts_bfffo_mem:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        add     addr, addr, base_disp
        b       bfextu_bfexts_bfffo_mem_3
        ALIGN(8)

// Reached from 27 dispatch table entries:
//     BFEXTU (An){ofs:wid},Dn
//     BFEXTS (An){ofs:wid},Dn
//     BFFFO (An){ofs:wid},Dn
//     BFEXTU (xxx).W{ofs:wid},Dn
//     BFEXTS (xxx).W{ofs:wid},Dn
//     BFFFO (xxx).W{ofs:wid},Dn
bfextu_bfexts_bfffo_mem_2:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// A field in memory.  The byte address is advanced by the offset divided
// by eight (arithmetically: offsets may be negative) and the remaining
// three bits are a shift.  Four bytes are loaded; a field that runs into a
// fifth byte has that byte fetched and merged in separately.  BFEXTU
// shifts the field down logically, BFEXTS arithmetically, and BFFFO counts
// leading zeros and adds the offset.  The result goes to its register
// through reg_access_base_disp.
//
// Continuation (via rtn_addr) of 30 dispatch table entries:
//     BFEXTU (d8,An,Xn){ofs:wid},Dn
//     BFEXTS (d8,An,Xn){ofs:wid},Dn
//     BFFFO (d8,An,Xn){ofs:wid},Dn
//     BFEXTU (xxx).L{ofs:wid},Dn
//     BFEXTU (d8,PC,Xn){ofs:wid},Dn
//     BFEXTS (xxx).L{ofs:wid},Dn
//     ... and 3 more forms
bfextu_bfexts_bfffo_mem_3:
        mtcrf   0x0F, immed_data                        // cr4..cr7 = immed_data[15:0]
        rlwinm  base_disp, immed_data, 26, 27, 31       // base_disp = immed_data[10:6]
        ori     data, code_ptr, reg_access_base_disp_L1 - cb
        rlwimi  data, immed_data, 24, 25, 27            // data[6:4] = immed_data[14:12]
        bltl    cr5, bfins_mem_3_L1
        srawi   rtn_addr, base_disp, 3                  // whole bytes of offset
        neg     immed_data, immed_data
        add     addr, addr, rtn_addr
        beql    cr6, bfins_mem_3_L2
        mtcrf   0x0F, disp_table                        // cr4..cr7 = disp_table[15:0]
        clrlwi  rtn_addr, base_disp, 29                 // bits of offset within the byte
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        cmplw   rtn_addr, immed_data
        mtctr   data
        bso     cr4, bfextu_bfexts_bfffo_mem_3_L1
        subfc   data, immed_data, base_disp             // data = base_disp - immed_data
        lwz     base_disp, 0(addr)
        addco   zero, zero, zero                        // V=0, C=0
        slw     base_disp, base_disp, rtn_addr
        bgtl    bfextu_bfexts_bfffo_mem_3_L2            // does the field reach a fifth byte ?
        srw     base_disp, base_disp, immed_data
        slw.    rtn_addr, base_disp, immed_data
        bnectr  cr4
        cntlzw  addr, base_disp                         // BFFFO: position of the first one bit
        add     base_disp, data, addr
        bctr
bfextu_bfexts_bfffo_mem_3_L1:
        lwz     base_disp, 0(addr)
        slw     base_disp, base_disp, rtn_addr
        bgtl    bfextu_bfexts_bfffo_mem_3_L2
        sraw.   base_disp, base_disp, immed_data        // base_disp = base_disp >> immed_data (arithmetic)
        addco   zero, zero, zero                        // V=0, C=0
        bctr
bfextu_bfexts_bfffo_mem_3_L2:
        lbz     addr, 4(addr)
        subfic  rtn_addr, rtn_addr, 8                   // rtn_addr = 8 - rtn_addr
        srw     addr, addr, rtn_addr
        addc    base_disp, base_disp, addr
        blr
        b       bfchg_bfclr_bfset
        ALIGN(64)

// BFCHG, BFCLR and BFSET on a register.  A mask with ones for the field is
// made by shifting -1 left by 32 minus the width and rotating it right by
// the offset.  N and Z come from the old field; then the register is
// changed under the mask according to the opcode still in disp_table.
//
// Reached from 24 dispatch table entries:
//     BFCHG Dn{ofs:wid}
//     BFCLR Dn{ofs:wid}
//     BFSET Dn{ofs:wid}
bfchg_bfclr_bfset:
        mtcrf   0x0F, prefetch_data                     // cr4..cr7 = prefetch_data[15:0]
        rlwinm  base_disp, prefetch_data, 26, 27, 31    // base_disp = prefetch_data[10:6]
        neg     immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bltl    cr5, bfins_mem_3_L1
        li      data, -1
        neg     base_disp, base_disp
        beql    cr6, bfins_mem_3_L2
        mtctr   addr
        mtcrf   0x0F, disp_table                        // cr4..cr7 = disp_table[15:0]
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        slw     data, data, immed_data                  // ones for the width, at the top
        rlwnm   data, data, base_disp, 0, 31            // rotated into place
        neg     rtn_addr, base_disp
        bctrl
        and     immed_data, base_disp, data
        rlwnm.  addr, immed_data, rtn_addr, 0, 31       // the old field, for N and Z
        addco   zero, zero, zero                        // V=0, C=0
        bne     cr4, bfchg_bfclr_bfset_L1
        or      base_disp, base_disp, data
        bsolr   cr4
bfchg_bfclr_bfset_L1:
        xor     base_disp, base_disp, data
        blr
        ALIGN(32)

// Reached from 24 dispatch table entries:
//     BFCHG (d16,An){ofs:wid}
//     BFCLR (d16,An){ofs:wid}
//     BFSET (d16,An){ofs:wid}
bfchg_bfclr_bfset_mem:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        add     addr, addr, base_disp
        b       bfchg_bfclr_bfset_mem_3

// Reached from 27 dispatch table entries:
//     BFCHG (An){ofs:wid}
//     BFCLR (An){ofs:wid}
//     BFSET (An){ofs:wid}
//     BFCHG (xxx).W{ofs:wid}
//     BFCLR (xxx).W{ofs:wid}
//     BFSET (xxx).W{ofs:wid}
bfchg_bfclr_bfset_mem_2:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Continuation (via rtn_addr) of 27 dispatch table entries:
//     BFCHG (d8,An,Xn){ofs:wid}
//     BFCLR (d8,An,Xn){ofs:wid}
//     BFSET (d8,An,Xn){ofs:wid}
//     BFCHG (xxx).L{ofs:wid}
//     BFCLR (xxx).L{ofs:wid}
//     BFSET (xxx).L{ofs:wid}
bfchg_bfclr_bfset_mem_3:
        mtcrf   0x0F, immed_data                        // cr4..cr7 = immed_data[15:0]
        rlwinm  base_disp, immed_data, 26, 27, 31       // base_disp = immed_data[10:6]
        bltl    cr5, bfins_mem_3_L1
        srawi   rtn_addr, base_disp, 3                  // rtn_addr = base_disp >> 3 (arithmetic)
        neg     immed_data, immed_data
        add     addr, addr, rtn_addr
        beql    cr6, bfins_mem_3_L2
        mtcrf   0x0F, disp_table                        // cr4..cr7 = disp_table[15:0]
        clrlwi  base_disp, base_disp, 29                // base_disp = base_disp & 0x00000007
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        subfc.  rtn_addr, base_disp, immed_data         // rtn_addr = immed_data - base_disp
        lwz     data, 0(addr)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        addco   zero, zero, zero                        // V=0, C=0
        blt     bfchg_bfclr_bfset_mem_3_L3
        li      rtn_addr, -1
        slw     rtn_addr, rtn_addr, immed_data
        srw     rtn_addr, rtn_addr, base_disp
        and     immed_data, data, rtn_addr
        bne     cr4, bfchg_bfclr_bfset_mem_3_L1
        or      data, data, rtn_addr
        bso     cr4, bfchg_bfclr_bfset_mem_3_L2
bfchg_bfclr_bfset_mem_3_L1:
        xor     data, data, rtn_addr
bfchg_bfclr_bfset_mem_3_L2:
        stw     data, 0(addr)
        slw.    immed_data, immed_data, base_disp
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
bfchg_bfclr_bfset_mem_3_L3:
        lbz     immed_data, 4(addr)
        addi    rtn_addr, rtn_addr, 8
        srw     immed_data, immed_data, rtn_addr
        or      immed_data, immed_data, data
        slw.    immed_data, immed_data, base_disp
        li      immed_data, -1
        srw     base_disp, immed_data, base_disp
        lbz     immed_data, 4(addr)
        slw     rtn_addr, base_disp, rtn_addr
        bne     cr4, bfchg_bfclr_bfset_mem_3_L4
        or      data, data, base_disp
        or      immed_data, immed_data, rtn_addr
        bso     cr4, bfchg_bfclr_bfset_mem_3_L5
bfchg_bfclr_bfset_mem_3_L4:
        xor     data, data, base_disp
        xor     immed_data, immed_data, rtn_addr
bfchg_bfclr_bfset_mem_3_L5:
        stw     data, 0(addr)
        stb     immed_data, 4(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        ALIGN(64)

// BFINS on a register: the source register's low bits are moved to the top
// by the shift that makes the mask (which also sets N and Z from the
// value inserted), rotated into place with it, and merged.
//
// Reached from 8 dispatch table entries:
//     BFINS Dn,Dn{ofs:wid}
bfins:
        mtcrf   0x0F, prefetch_data                     // cr4..cr7 = prefetch_data[15:0]
        ori     data, code_ptr, reg_access_base_disp - cb
        rlwimi  data, prefetch_data, 24, 25, 27         // data[6:4] = prefetch_data[14:12]
        neg     immed_data, prefetch_data
        beql    cr6, bfins_mem_3_L2
        mtlr    data
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        blrl
        slw.    data, base_disp, immed_data             // the value, left-justified; N and Z
        rlwinm  base_disp, prefetch_data, 26, 27, 31    // base_disp = prefetch_data[10:6]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bltl    cr5, bfins_mem_3_L1
        mtlr    addr
        li      rtn_addr, -1
        neg     addr, base_disp
        slw     rtn_addr, rtn_addr, immed_data
        blrl
        rlwnm   rtn_addr, rtn_addr, addr, 0, 31         // rtn_addr = rotl(rtn_addr, addr) & 0xFFFFFFFF
        rlwnm   data, data, addr, 0, 31                 // data = rotl(data, addr) & 0xFFFFFFFF
        andc    base_disp, base_disp, rtn_addr          // clear the field, then put the value in
        addco   base_disp, base_disp, data
        blr
        ALIGN(32)

// Reached from 9 dispatch table entries:
//     BFINS Dn,(An){ofs:wid}
//     BFINS Dn,(xxx).W{ofs:wid}
bfins_mem:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Continuation (via rtn_addr) of 9 dispatch table entries:
//     BFINS Dn,(d8,An,Xn){ofs:wid}
//     BFINS Dn,(xxx).L{ofs:wid}
bfins_mem_2:
        mtcrf   0x0F, immed_data                        // cr4..cr7 = immed_data[15:0]
        ori     data, code_ptr, reg_access_base_disp - cb
        rlwinm  base_disp, immed_data, 26, 27, 31       // base_disp = immed_data[10:6]
        rlwimi  data, immed_data, 24, 25, 27            // data[6:4] = immed_data[14:12]
        bltl    cr5, bfins_mem_3_L1
        srawi   rtn_addr, base_disp, 3                  // rtn_addr = base_disp >> 3 (arithmetic)
        neg     immed_data, immed_data
        add     addr, addr, rtn_addr
        beql    cr6, bfins_mem_3_L2
        mtlr    data
        clrlwi. data, base_disp, 29                     // data = base_disp & 0x00000007
        clrlwi  immed_data, immed_data, 27              // immed_data = immed_data & 0x0000001F
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        blrl
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        bne     bfins_mem_2_L2
        clrlwi. rtn_addr, immed_data, 29                // rtn_addr = immed_data & 0x00000007
        bne     bfins_mem_2_L2
        slw.    base_disp, base_disp, immed_data
        subfic  rtn_addr, immed_data, 32                // rtn_addr = 32 - immed_data
        srwi    rtn_addr, rtn_addr, 3
        mtxer   rtn_addr
        stswx   base_disp, 0, addr
bfins_mem_2_L1:
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
bfins_mem_2_L2:
        cmplw   cr7, data, immed_data
        slw.    base_disp, base_disp, immed_data
        bgt     cr7, bfins_mem_2_L4
        li      rtn_addr, -1
        slw     rtn_addr, rtn_addr, immed_data
bfins_mem_2_L3:
        lwz     immed_data, 0(addr)
        srw     rtn_addr, rtn_addr, data
        srw     base_disp, base_disp, data
        andc    immed_data, immed_data, rtn_addr        // immed_data = immed_data & ~rtn_addr
        addco   immed_data, immed_data, base_disp
        stw     immed_data, 0(addr)
        b       bfins_mem_2_L1
bfins_mem_2_L4:
        li      rtn_addr, -0x100
        slw     rtn_addr, rtn_addr, immed_data
        lbz     immed_data, 4(addr)
        srw     rtn_addr, rtn_addr, data
        andc    immed_data, immed_data, rtn_addr        // immed_data = immed_data & ~rtn_addr
        slwi    rtn_addr, base_disp, 8
        srw     rtn_addr, rtn_addr, data
        or      immed_data, immed_data, rtn_addr
        li      rtn_addr, -1
        stb     immed_data, 4(addr)
        b       bfins_mem_2_L3

// Reached from 8 dispatch table entries:
//     BFINS Dn,(d16,An){ofs:wid}
bfins_mem_3:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        add     addr, addr, base_disp
        b       bfins_mem_2
bfins_mem_3_L1:
        ori     rtn_addr, code_ptr, reg_access_base_disp - cb
        rlwimi  rtn_addr, base_disp, 4, 25, 27          // rtn_addr[6:4] = base_disp[2:0]
        mtctr   rtn_addr
        bctr
bfins_mem_3_L2:
        ori     rtn_addr, code_ptr, reg_access_rtn_addr_L2 - cb
        rlwimi  rtn_addr, immed_data, 3, 26, 28         // rtn_addr[5:3] = immed_data[2:0]
        mtctr   rtn_addr
        bctr
bfins_mem_3_L3:
        lhaux   prefetch_data, pc, prefetch_data

// Reached from 2 dispatch table entries:
//     JMP (d16,PC)
//     BRA.W <label>
jmp_bra_mem:
        rlwimi  disp_table, pc, 20, 11, 11              // disp_table[20] = pc[0]
        mtctr   dr_entry
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        btctr   cr_dr_active
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       jmp_bra_mem_L1
        ALIGN(32)
jmp_bra_mem_L1:
        lwz     data, 0(pc)

// Reached from 1 dispatch table entry:
//     BRA.L <label>
bra_l:
        lhaux   prefetch_data, pc, data
        rlwimi  disp_table, pc, 20, 11, 11              // disp_table[20] = pc[0]
        mtctr   dr_entry
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        btctr   cr_dr_active
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       jmp_mem
        ALIGN(32)

// Continuation (via rtn_addr) of 8 dispatch table entries:
//     JMP (d8,An,Xn)
//     JMP (d8,PC,Xn)
jmp_mem:
        mr      pc, addr

// Reached from 18 dispatch table entries:
//     JMP (An)
//     JMP (d16,An)
//     JMP (xxx).W
//     JMP (xxx).L
jmp_mem_2:
        lha     prefetch_data, 0(pc)
        rlwimi  disp_table, pc, 20, 11, 11              // disp_table[20] = pc[0]
        mtctr   dr_entry
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        btctr   cr_dr_active
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       bsr_s
        ALIGN(32)

// Reached from 127 dispatch table entries:
//     BSR.S <label>
bsr_s:
        lha     prefetch_data, 0(addr)
        stwu    pc, -4(a7)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtctr   dr_entry
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lha     prefetch_data, 2(addr)
        addi    pc, addr, 2
        btctr   cr_dr_active
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       jsr_bsr_mem
        ALIGN(32)

// Reached from 2 dispatch table entries:
//     JSR (d16,PC)
//     BSR.W <label>
jsr_bsr_mem:
        rlwimi  disp_table, prefetch_data, 20, 11, 11   // disp_table[20] = prefetch_data[0]
        rlwimi  disp_table, data, 3, 13, 28             // DECODE1: disp_table[18:3] = opcode in data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        mtctr   dr_entry
        addi    pc, pc, 2
        stwu    pc, -4(a7)
        lhaux   prefetch_data, pc, prefetch_data
        btctr   cr_dr_active
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       rts
        ALIGN(32)

// Reached from 1 dispatch table entry:
//     RTS
rts:
        lha     prefetch_data, 0(pc)
        rlwimi  disp_table, pc, 20, 11, 11              // disp_table[20] = pc[0]
        mtctr   dr_entry
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
