        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 6(pc)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        ALIGN(64)

// Reached from 1 dispatch table entry:
//     BVS.L <label>
bvs_l:
        mfxer   data
        rlwinm  data, data, 8, 24, 27                   // data = data[31:28] << 4
        mtcrf   0x02, data                              // cr6 = data[7:4]
        bgt     cr6, jmp_bra_mem_L1
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 6(pc)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 1 dispatch table entry:
//     BMI.L <label>
bmi_l:
        blt     jmp_bra_mem_L1
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 6(pc)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        ALIGN(64)

// Reached from 1 dispatch table entry:
//     BGT.L <label>
bgt_l:
        beq     bcc_l_L1

// Reached from 1 dispatch table entry:
//     BGE.L <label>
bge_l:
        mfxer   data
        rlwinm  data, data, 8, 24, 27                   // data = data[31:28] << 4
        mtcrf   0x02, data                              // cr6 = data[7:4]
        creqv   4*cr6+lt, lt, 4*cr6+gt                  // cr6.lt = ~(cr0.lt ^ cr6.gt)
        blt     cr6, jmp_bra_mem_L1
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 6(pc)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        b       ble_l
        ALIGN(64)

// Reached from 1 dispatch table entry:
//     BLE.L <label>
ble_l:
        beq     jmp_bra_mem_L1

// Reached from 1 dispatch table entry:
//     BLT.L <label>
blt_l:
        mfxer   data
        rlwinm  data, data, 8, 24, 27                   // data = data[31:28] << 4
        mtcrf   0x02, data                              // cr6 = data[7:4]
        crxor   4*cr6+lt, lt, 4*cr6+gt                  // cr6.lt = cr0.lt ^ cr6.gt
        blt     cr6, jmp_bra_mem_L1
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 6(pc)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 1778 dispatch table entries:
//     BHI.S <label>
//     BLS.S <label>
//     BCC.S <label>
//     BCS.S <label>
//     BNE.S <label>
//     BEQ.S <label>
//     ... and 8 more forms
bcc_s_2:
        ori     base_disp, code_ptr, condition_truth_table - cb
        mfxer   immed_data
        rlwinm  data, disp_table, 23, 26, 29            // data = disp_table[14:11] << 2
        mfcr    rtn_addr
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwnm   data, data, immed_data, 31, 31          // data = rotl(data, immed_data) & 0x00000001
        mtcrf   0x01, data                              // cr7 = data[3:0]
        bso     cr7, bra_s_2
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 127 dispatch table entries:
//     BSR.S <label>
bsr_s_2:
        stwu    pc, -4(a7)

// Reached from 127 dispatch table entries:
//     BRA.S <label>
bra_s_2:
        addi    data, pc, -2
        stw     data, trace_pc(EmulatorStatePtr)
        lha     prefetch_data, 0(addr)
        mr      pc, addr
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        b       process_special_event
        b       dbcc_w_dn
        ALIGN(64)

// Reached from 80 dispatch table entries:
//     DBHI.W Dn,<label>
//     DBLS.W Dn,<label>
//     DBCC.W Dn,<label>
//     DBCS.W Dn,<label>
//     DBVC.W Dn,<label>
//     DBVS.W Dn,<label>
//     ... and 4 more forms
dbcc_w_dn:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, condition_truth_table - cb
        mfxer   immed_data
        rlwinm  data, disp_table, 23, 26, 29            // data = disp_table[14:11] << 2
        mfcr    rtn_addr
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwnm   data, data, immed_data, 31, 31          // data = rotl(data, immed_data) & 0x00000001
        cmplwi  cr6, data, 0x0000
        beqlr   cr6
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        b       fetch
        b       scc_b_dn
        ALIGN(64)

// Reached from 112 dispatch table entries:
//     SHI.B Dn
//     SLS.B Dn
//     SCC.B Dn
//     SCS.B Dn
//     SNE.B Dn
//     SEQ.B Dn
//     ... and 8 more forms
scc_b_dn:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, condition_truth_table - cb
        mfxer   immed_data
        rlwinm  data, disp_table, 23, 26, 29            // data = disp_table[14:11] << 2
        mfcr    rtn_addr
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwnm   data, data, immed_data, 31, 31          // data = rotl(data, immed_data) & 0x00000001
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        neg     data, data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        blr
        ALIGN(64)

// Reached from 135 dispatch table entries:
//     ST.B (d16,An)
//     SHI.B (d16,An)
//     SLS.B (d16,An)
//     SCC.B (d16,An)
//     SCS.B (d16,An)
//     SNE.B (d16,An)
//     ... and 24 more forms
scc_b_mem:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Reached from 120 dispatch table entries:
//     ST.B (An)
//     SHI.B (An)
//     SLS.B (An)
//     SCC.B (An)
//     SCS.B (An)
//     SNE.B (An)
//     ... and 9 more forms
// Continuation (via rtn_addr) of 272 dispatch table entries:
//     ST.B (An)+
//     ST.B (d8,An,Xn)
//     SF.B (An)+
//     SF.B (d8,An,Xn)
//     SHI.B (An)+
//     SHI.B (d8,An,Xn)
//     ... and 42 more forms
scc_b_mem_2:
        ori     base_disp, code_ptr, condition_truth_table - cb
        mfxer   immed_data
        rlwinm  data, disp_table, 23, 26, 29            // data = disp_table[14:11] << 2
        mfcr    rtn_addr
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwnm   data, data, immed_data, 31, 31          // data = rotl(data, immed_data) & 0x00000001
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        neg     data, data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        stb     data, 0(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// One 32-bit truth table per 68K condition code (T, F, HI, LS, CC, CS,
// NE, EQ, VC, VS, PL, MI, GE, LT, GT, LE).  The current N, Z, V and C
// flags are gathered into a 5-bit rotate count; rotating the table word
// by it leaves the condition's value in the low bit.  Used where a
// condition has to be evaluated without a branch (Scc, TRAPcc, and the
// trace logic's look at DBcc and Bcc).
condition_truth_table:
        .long   0xFFFFFFFF
        .long   0x00000000
        .long   0x41414141
        .long   0xBEBEBEBE
        .long   0x55555555
        .long   0xAAAAAAAA
        .long   0xE1E1E1E1
        .long   0x1E1E1E1E
        .long   0x99999999
        .long   0x66666666
        .long   0xFFFE0001
        .long   0x0001FFFE
        .long   0x99986667
        .long   0x66679998
        .long   0x81806061
        .long   0x7E7F9F9E

// ===========================================================================
// MOVEM
// ===========================================================================
// The register list - the word after the opcode, already in prefetch_data
// when a routine is entered - is copied into the condition register with
// mtcrf, one bit per register, and the transfer is sixteen conditional
// loads or stores in a row.  There is no loop and no counting of bits.
//
// The short routines here are the -(An) and (An)+ forms for each address
// register: they set addr, call the common code, and put the final address
// back in the register.
//
// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem:
        addi    addr, a0, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list:
        bl      movem_l_mem_list_4_L3
        add     a0, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_2:
        addi    addr, a1, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_2:
        bl      movem_l_mem_list_4_L3
        add     a1, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_3:
        addi    addr, a2, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_3:
        bl      movem_l_mem_list_4_L3
        add     a2, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_4:
        addi    addr, a3, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_4:
        bl      movem_l_mem_list_4_L3
        add     a3, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_5:
        addi    addr, a4, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_5:
        bl      movem_l_mem_list_4_L3
        add     a4, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_6:
        addi    addr, a5, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_6:
        bl      movem_l_mem_list_4_L3
        add     a5, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     MOVEM.W <list>,-(An)
//     MOVEM.L <list>,-(An)
movem_list_mem_7:
        addi    addr, a6, 4

// Reached from 2 dispatch table entries:
//     MOVEM.W (An)+,<list>
//     MOVEM.L (An)+,<list>
movem_mem_list_7:
        bl      movem_l_mem_list_4_L3
        add     a6, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 1 dispatch table entry:
//     MOVEM.W <list>,-(An)
movem_w_list_mem:
        addi    addr, a7, 4

// Reached from 1 dispatch table entry:
//     MOVEM.W (An)+,<list>
movem_w_mem_list:
        bl      movem_l_mem_list_4_L3
        add     a7, addr, base_disp
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// MOVEM.L <list>,-(A7), opcode 48E7.  The table entry has ORed 0x0F38 into
// the list: if the result is 0x0F38 the list names nothing outside D4-D7
// and A2-A4, the registers a compiled procedure saves, and only those
// seven are tested.  Other lists go to the general code.
//
// Reached from 1 dispatch table entry:
//     MOVEM.L <list>,-(An)
movem_l_list_mem:
        cmpwi   cr7, data, 0xF38                        // nothing but D4-D7/A2-A4 ?
        mr      addr, a7
        bne     cr7, movem_l_list_mem_4_L18
        mtcrf   0x0F, prefetch_data                     // cr4-cr7 = the register list
        lha     immed_data, 2(pc)                       // the opcode after the list
        lhau    prefetch_data, 4(pc)                    // PREFETCH: pc += 4, load the word there
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        blt     cr7, movem_l_list_mem_L7
        bso     cr6, movem_l_list_mem_L8
movem_l_list_mem_L1:
        beq     cr6, movem_l_list_mem_L9
movem_l_list_mem_L2:
        bso     cr5, movem_l_list_mem_L10
movem_l_list_mem_L3:
        beq     cr5, movem_l_list_mem_L11
movem_l_list_mem_L4:
        bgt     cr5, movem_l_list_mem_L12
movem_l_list_mem_L5:
        blt     cr5, movem_l_list_mem_L13
movem_l_list_mem_L6:
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event
        ALIGN(8)
movem_l_list_mem_L7:
        stwu    a4, -4(a7)                              // the stores, highest register first
        bns     cr6, movem_l_list_mem_L1
movem_l_list_mem_L8:
        stwu    a3, -4(a7)
        bne     cr6, movem_l_list_mem_L2
movem_l_list_mem_L9:
        stwu    a2, -4(a7)
        bns     cr5, movem_l_list_mem_L3
movem_l_list_mem_L10:
        stwu    d7, -4(a7)
        bne     cr5, movem_l_list_mem_L4
movem_l_list_mem_L11:
        stwu    d6, -4(a7)
        ble     cr5, movem_l_list_mem_L5
movem_l_list_mem_L12:
        stwu    d5, -4(a7)
        bge     cr5, movem_l_list_mem_L6
movem_l_list_mem_L13:
        stwu    d4, -4(a7)
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event
        b       movem_l_mem_list
        ALIGN(64)

// MOVEM.L (A7)+,<list>, opcode 4CDF: the same short cut for a list within
// D4-D7/A2-A4 (0x1CF0 in this direction), taken only when no special event
// is pending.  If the instruction that follows is UNLK A6 (4E5E) - the end
// of a procedure - the two are done together.
//
// Reached from 1 dispatch table entry:
//     MOVEM.L (An)+,<list>
movem_l_mem_list:
        cmpwi   cr7, data, 0x1CF0
        addi    addr, a7, -4
        bt      cr_special_event_pending, movem_l_mem_list_4_L2
        bne     cr7, movem_l_mem_list_4_L2
        lha     immed_data, 2(pc)
        mtcrf   0x0E, prefetch_data                     // cr4..cr6 = prefetch_data[15:4]
        cmpwi   cr7, immed_data, 0x4E5E                 // is the next instruction UNLK A6 ?
        lhau    prefetch_data, 4(pc)                    // PREFETCH: pc += 4, load the word there
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        beq     cr7, movem_l_mem_list_2_L1
        bso     cr6, movem_l_mem_list_L7
        beq     cr6, movem_l_mem_list_L8
movem_l_mem_list_L1:
        bgt     cr6, movem_l_mem_list_L9
movem_l_mem_list_L2:
        blt     cr6, movem_l_mem_list_L10
movem_l_mem_list_L3:
        bgt     cr5, movem_l_mem_list_L11
movem_l_mem_list_L4:
        blt     cr5, movem_l_mem_list_L12
movem_l_mem_list_L5:
        bso     cr4, movem_l_mem_list_L13
movem_l_mem_list_L6:
        addi    a7, addr, 4
        bctr
movem_l_mem_list_L7:
        lwzu    d4, 4(addr)
        bne     cr6, movem_l_mem_list_L1
movem_l_mem_list_L8:
        lwzu    d5, 4(addr)
        ble     cr6, movem_l_mem_list_L2
movem_l_mem_list_L9:
        lwzu    d6, 4(addr)
        bge     cr6, movem_l_mem_list_L3
movem_l_mem_list_L10:
        lwzu    d7, 4(addr)
        ble     cr5, movem_l_mem_list_L4
movem_l_mem_list_L11:
        lwzu    a2, 4(addr)
        bge     cr5, movem_l_mem_list_L5
movem_l_mem_list_L12:
        lwzu    a3, 4(addr)
        bns     cr4, movem_l_mem_list_L6
movem_l_mem_list_L13:
        lwzu    a4, 4(addr)
        addi    a7, addr, 4
        bctr
        b       movem_l_mem_list_2
        ALIGN(64)

// MOVEM.L (d16,An),<list> and its relatives, with the same short cut and
// the same look ahead for UNLK A6.
//
// Reached from 10 dispatch table entries:
//     MOVEM.L (d16,An),<list>
//     MOVEM.L (xxx).W,<list>
//     MOVEM.L (d16,PC),<list>
movem_l_mem_list_2:
        ori     data, prefetch_data, 0x1CF0
        cmpwi   cr7, data, 0x1CF0
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        bt      cr_special_event_pending, movem_l_mem_list_4_L1
        bne     cr7, movem_l_mem_list_4_L1
        mtcrf   0x0E, prefetch_data                     // cr4..cr6 = prefetch_data[15:4]
        lha     immed_data, 2(pc)
        add     addr, addr, base_disp
        lhau    prefetch_data, 4(pc)                    // PREFETCH: pc += 4, load the word there
        cmpwi   cr7, immed_data, 0x4E5E
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
movem_l_mem_list_2_L1:
        bso     cr6, movem_l_mem_list_2_L8
        beq     cr6, movem_l_mem_list_2_L9
movem_l_mem_list_2_L2:
        bgt     cr6, movem_l_mem_list_2_L10
movem_l_mem_list_2_L3:
        blt     cr6, movem_l_mem_list_2_L11
movem_l_mem_list_2_L4:
        cmpwi   cr6, prefetch_data, 0x4E75
        bgt     cr5, movem_l_mem_list_2_L12
movem_l_mem_list_2_L5:
        blt     cr5, movem_l_mem_list_2_L13
movem_l_mem_list_2_L6:
        bso     cr4, movem_l_mem_list_2_L14
        bnectr  cr7
        lwz     addr, 0(a6)
        beq     cr6, movem_l_mem_list_2_L15
