        rlwinm  immed_data, disp_table, 29, 16, 28      // immed_data = disp_table[18:6] << 3
        rlwimi  immed_data, zero, 0, 20, 22             // immed_data[11:9] = zero[11:9]
        cmplwi  cr7, immed_data, 0x8100                 // below ABCD: SBCD
        cmplwi  cr6, immed_data, 0x8180                 // PACK or UNPK
        ble     cr7, bcd_dn_dn_L1
        ble     cr6, bcd_dn_dn_L2
        mtxer   ccr_x                                   // X is the carry in
        clrlwi  base_disp, addr, 24                     // base_disp = addr & 0x000000FF
        crmove  4*cr7+so, eq
        adde    immed_data, data, base_disp             // binary sum
        rlwinm  base_disp, base_disp, 0, 24, 27         // base_disp = base_disp[7:4] << 4
        subfic  rtn_addr, immed_data, 153               // rtn_addr = 153 - immed_data
        rlwinm  data, data, 0, 24, 27                   // data = data[7:4] << 4
        subf    base_disp, base_disp, immed_data        // base_disp = immed_data - base_disp
        slwi    immed_data, immed_data, 24
        subf    base_disp, data, base_disp              // base_disp = base_disp - data
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        subfic  base_disp, base_disp, 9                 // base_disp = 9 - base_disp
        addco   ccr_x, rtn_addr, rtn_addr
        rlwimi  rtn_addr, base_disp, 28, 4, 7           // rtn_addr[27:24] = base_disp[31:28]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        andis.  rtn_addr, rtn_addr, 0x6600              // 0x66 where a digit needs correcting
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        add.    immed_data, immed_data, rtn_addr
        rlwimi  addr, immed_data, 8, 24, 31             // addr[7:0] = immed_data[31:24]
        crand   eq, eq, 4*cr7+so                        // Z stays clear if it was clear
        blr
bcd_dn_dn_L1:
        rlwinm  rtn_addr, ccr_x, 3, 31, 31              // rtn_addr = ccr_x[29]
        clrlwi  base_disp, addr, 24                     // base_disp = addr & 0x000000FF
        crmove  4*cr7+so, eq
        subf    immed_data, data, base_disp             // immed_data = base_disp - data
        rlwinm  base_disp, base_disp, 0, 24, 27         // base_disp = base_disp[7:4] << 4
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        rlwinm  data, data, 0, 24, 27                   // data = data[7:4] << 4
        subf    base_disp, base_disp, immed_data        // base_disp = immed_data - base_disp
        rlwinm  rtn_addr, immed_data, 8, 24, 27         // rtn_addr = immed_data[31:28] << 4
        add     base_disp, data, base_disp
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwimi  rtn_addr, base_disp, 4, 28, 31          // rtn_addr[3:0] = base_disp[31:28]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        andi.   rtn_addr, rtn_addr, 0x0066
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        addco   ccr_x, immed_data, immed_data
        slwi.   rtn_addr, immed_data, 24
        crand   eq, eq, 4*cr7+so                        // cr0.eq = cr0.eq & cr7.so
        rlwimi  addr, immed_data, 0, 24, 31             // addr[7:0] = immed_data[7:0]
        blr
bcd_dn_dn_L2:
        lhau    rtn_addr, 2(pc)                         // rtn_addr = next word: pc += 2, load the word there
        beq     cr6, bcd_dn_dn_L3
        add     data, data, prefetch_data
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        rlwimi  data, data, 28, 24, 27                  // data[7:4] = data[11:8]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        rlwimi  addr, data, 0, 24, 31                   // addr[7:0] = data[7:0]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        blr
bcd_dn_dn_L3:
        clrlwi  immed_data, data, 28                    // immed_data = data & 0x0000000F
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        rlwimi  immed_data, data, 4, 20, 23             // immed_data[11:8] = data[7:4]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        add     data, immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwimi  addr, data, 0, 16, 31                   // addr[15:0] = data[15:0]
        blr
        b       sbcd_pack_etc_mem_mem
        ALIGN(32)

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem:
        addi    addr, a0, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a0, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_2:
        addi    addr, a1, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a1, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_3:
        addi    addr, a2, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a2, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_4:
        addi    addr, a3, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a3, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_5:
        addi    addr, a4, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a4, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_6:
        addi    addr, a5, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a5, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 32 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     UNPK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_etc_mem_mem_7:
        addi    addr, a6, -1
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a6, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 24 dispatch table entries:
//     SBCD.B -(An),-(An)
//     PACK -(An),-(An),#<adj>
//     ABCD.B -(An),-(An)
sbcd_pack_abcd_mem_mem:
        addi    addr, a7, -2
        bl      sbcd_pack_abcd_mem_mem_L1
        mr      a7, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event
sbcd_pack_abcd_mem_mem_L1:
        rlwinm  immed_data, disp_table, 29, 16, 28      // immed_data = disp_table[18:6] << 3
        rlwimi  immed_data, zero, 0, 20, 22             // immed_data[11:9] = zero[11:9]
        cmplwi  cr7, immed_data, 0x8108
        cmplwi  cr6, immed_data, 0x8188
        beq     cr7, sbcd_pack_abcd_mem_mem_L2
        ble     cr6, pack_unpk_adjust
        lbz     base_disp, 0(addr)
        mtxer   ccr_x
        crmove  4*cr7+so, eq
        adde    immed_data, data, base_disp             // immed_data = data + base_disp + CA
        rlwinm  base_disp, base_disp, 0, 24, 27         // base_disp = base_disp[7:4] << 4
        subfic  rtn_addr, immed_data, 153               // rtn_addr = 153 - immed_data
        rlwinm  data, data, 0, 24, 27                   // data = data[7:4] << 4
        subf    base_disp, base_disp, immed_data        // base_disp = immed_data - base_disp
        slwi    immed_data, immed_data, 24
        subf    base_disp, data, base_disp              // base_disp = base_disp - data
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        subfic  base_disp, base_disp, 9                 // base_disp = 9 - base_disp
        addco   ccr_x, rtn_addr, rtn_addr
        rlwimi  rtn_addr, base_disp, 28, 4, 7           // rtn_addr[27:24] = base_disp[31:28]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        andis.  rtn_addr, rtn_addr, 0x6600
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        add.    immed_data, immed_data, rtn_addr
        srwi    immed_data, immed_data, 24
        crand   eq, eq, 4*cr7+so                        // cr0.eq = cr0.eq & cr7.so
        stb     immed_data, 0(addr)
        blr
sbcd_pack_abcd_mem_mem_L2:
        lbz     base_disp, 0(addr)
        rlwinm  rtn_addr, ccr_x, 3, 31, 31              // rtn_addr = ccr_x[29]
        crmove  4*cr7+so, eq
        subf    immed_data, data, base_disp             // immed_data = base_disp - data
        rlwinm  base_disp, base_disp, 0, 24, 27         // base_disp = base_disp[7:4] << 4
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        rlwinm  data, data, 0, 24, 27                   // data = data[7:4] << 4
        subf    base_disp, base_disp, immed_data        // base_disp = immed_data - base_disp
        rlwinm  rtn_addr, immed_data, 8, 24, 27         // rtn_addr = immed_data[31:28] << 4
        add     base_disp, data, base_disp
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwimi  rtn_addr, base_disp, 4, 28, 31          // rtn_addr[3:0] = base_disp[31:28]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        andi.   rtn_addr, rtn_addr, 0x0066
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        addco   ccr_x, immed_data, immed_data
        slwi.   rtn_addr, immed_data, 24
        crand   eq, eq, 4*cr7+so                        // cr0.eq = cr0.eq & cr7.so
        stb     immed_data, 0(addr)
        blr

// PACK and UNPK: step over the adjustment word, leaving the opcode after
// it in rtn_addr for DECODE1.
pack_unpk_adjust:
        lhau    rtn_addr, 2(pc)                         // rtn_addr = next word: pc += 2, load the word there
        beq     cr6, unpk_store
        add     data, data, prefetch_data
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        rlwimi  data, data, 28, 24, 27                  // data[7:4] = data[11:8]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        stb     data, 0(addr)
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        blr

// UNPK -(Ay),-(A7),#<adjustment>.
//
// DEFECT IN THE ORIGINAL CODE.  The other forms of UNPK reach the common
// code at unpk_store through pack_unpk_adjust, which first executes
// "lhau rtn_addr, 2(pc)" to step over the adjustment word and pick up
// the next opcode.  This entry calls unpk_store directly.  As a result
// DECODE1 there uses whatever happens to be in rtn_addr as the next
// opcode, and pc ends up 2 short.  Unpacking BCD onto the stack is not
// something software does, which is presumably why it was never noticed;
// the same code is in the Power Macintosh 8600/9600 ROM.
//
// Reached from 8 dispatch table entries:
//     UNPK -(An),-(An),#<adj>
unpk_to_a7:
        addi    addr, a7, -1
        bl      unpk_store                              // should be pack_unpk_adjust
        mr      a7, addr
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

unpk_store:
        clrlwi  immed_data, data, 28                    // immed_data = data & 0x0000000F
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        rlwimi  immed_data, data, 4, 20, 23             // immed_data[11:8] = data[7:4]
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        add     data, immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        sthu    data, -1(addr)
        blr

// Reached from 9 dispatch table entries:
//     NBCD.B (d16,An)
//     NBCD.B (xxx).W
nbcd_b_mem:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Reached from 8 dispatch table entries:
//     NBCD.B (An)
// Continuation (via rtn_addr) of 17 dispatch table entries:
//     NBCD.B (An)+
//     NBCD.B (d8,An,Xn)
//     NBCD.B (xxx).L
nbcd_b_mem_2:
        lbz     data, 0(addr)
        rlwinm  rtn_addr, ccr_x, 3, 31, 31              // rtn_addr = ccr_x[29]
        crmove  4*cr7+so, eq
        subf    immed_data, data, zero                  // immed_data = zero - data
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        rlwinm  data, data, 0, 24, 27                   // data = data[7:4] << 4
        rlwinm  rtn_addr, immed_data, 8, 24, 27         // rtn_addr = immed_data[31:28] << 4
        add     base_disp, data, immed_data
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwimi  rtn_addr, base_disp, 4, 28, 31          // rtn_addr[3:0] = base_disp[31:28]
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        andi.   rtn_addr, rtn_addr, 0x0066
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        subf    immed_data, rtn_addr, immed_data        // immed_data = immed_data - rtn_addr
        addco   ccr_x, immed_data, immed_data
        stb     immed_data, 0(addr)
        slwi.   rtn_addr, immed_data, 24
        crand   eq, eq, 4*cr7+so                        // cr0.eq = cr0.eq & cr7.so
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     MOVE.W SR,Dn
move_w_sr_dn:
        lwz     rtn_addr, 0x81C(EmulatorStatePtr)
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        mtlr    rtn_addr
        rlwimi  data, ccr_x, 7, 27, 27                  // data[4] = ccr_x[29]
        bf      cr_supervisor, move_from_sr_user
        blr

// Reached from 8 dispatch table entries:
//     MOVE.W SR,(An)
move_w_sr_mem:
        bfl     cr_supervisor, privilege_check_failed
move_w_sr_mem_L1:
        lwz     rtn_addr, 0x820(EmulatorStatePtr)
        b       move_w_sr_mem_5_L1

// Reached from 9 dispatch table entries:
//     MOVE.W SR,(d16,An)
//     MOVE.W SR,(xxx).W
move_w_sr_mem_2:
        bfl     cr_supervisor, privilege_check_failed
        lwz     rtn_addr, 0x820(EmulatorStatePtr)
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        b       move_w_sr_mem_5_L1

// Reached from 17 dispatch table entries:
//     MOVE.W SR,(An)+
//     MOVE.W SR,(d8,An,Xn)
//     MOVE.W SR,(xxx).L
move_w_sr_mem_3:
        mtctr   addr
        bfl     cr_supervisor, privilege_check_failed
        lwz     rtn_addr, 0x820(EmulatorStatePtr)
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        rlwimi  data, ccr_x, 7, 27, 27                  // data[4] = ccr_x[29]
        bctr

// Reached from 7 dispatch table entries:
//     MOVE.W SR,-(An)
move_w_sr_mem_4:
        mtctr   addr
        li      data, -2
        bfl     cr_supervisor, privilege_check_failed
        ori     rtn_addr, code_ptr, move_w_sr_mem_L1 - cb
        bctr

// Reached from 1 dispatch table entry:
//     MOVE.W SR,-(An)
move_w_sr_mem_5:
        bfl     cr_supervisor, privilege_check_failed
        lwz     rtn_addr, 0x820(EmulatorStatePtr)
        addi    a7, a7, -2
move_w_sr_mem_5_L1:
        mtlr    rtn_addr
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        rlwimi  data, ccr_x, 7, 27, 27                  // data[4] = ccr_x[29]
        blr

// Load the 68K condition codes from the low five bits of data: N and Z
// into CR0, V and C into XER, X into ccr_x.  Continues through a
// replaceable handler.
set_ccr:
        lwz     base_disp, write_sr_handler(EmulatorStatePtr)
        rlwinm  immed_data, data, 27, 2, 2              // immed_data = data[2] << 29
        mtctr   base_disp
        rlwinm  ccr_x, data, 25, 2, 2                   // ccr_x = data[4] << 29
        rlwimi  immed_data, data, 28, 0, 0              // immed_data[31] = data[3]
        rlwinm  base_disp, data, 29, 1, 2               // base_disp = data[1:0] << 29
        mtcrf   0x80, immed_data                        // cr0 = immed_data[31:28]
        mtxer   base_disp
        bctr

// ===========================================================================
// Writing the status register
// ===========================================================================
// Load the upper byte of the SR from data (bits 15:8).  Everything that
// changes the SR comes through here, by way of handler slot +0x818:
// MOVE to SR, ANDI/ORI/EORI to SR, STOP, RTE.
//
// - The interrupt mask is copied into sr_and_flags.  If the kernel is
// signalling an interrupt above the new mask, or the private request
// level is non-zero, the special event flag is set so that it is
// taken at the next instruction boundary.  When the kernel's level
// byte says priorities need re-evaluating, PrioritizeInterrupts is
// called first.
// - cr_dr_active is recomputed: translated code is not used while a
// trace bit or a test-mode flag is set.
// - If T1, T0, S and M are all unchanged, that is all.
// - Otherwise a7 is stored in the slot of the outgoing stack pointer and
// loaded from the slot of the incoming one (stack_pointer_slots, indexed
// by S and M), cr_supervisor is updated, and a set trace bit raises the
// special event flag.
write_sr:
        eieio
        mr      immed_data, data
        rlwimi  immed_data, sr_and_flags, 8, 16, 19     // immed_data[15:12] = sr_and_flags[7:4]
        cmplw   cr7, data, immed_data                   // would T1, T0, S and M be unchanged?
        rlwimi  sr_and_flags, data, 24, 29, 31          // new interrupt mask
        li      base_disp, 0x4C0
        and     base_disp, base_disp, sr_and_flags
        cmpwi   cr6, base_disp, 0
        crand   cr_dr_active, cr_dr_enabled, 4*cr6+eq   // use translated code only if no trace or test-mode bit
        lbz     base_disp, interrupt_level(EmulatorStatePtr)
        lwz     immed_data, 0x1D0(EmulatorStatePtr)
        cmpwi   cr6, immed_data, 0
        rlwinm  immed_data, data, 24, 29, 31            // immed_data = data[10:8]
        bt_likely 4*cr6+eq, write_sr_L1
        crset   cr_special_event_pending
write_sr_L1:
        bf      cr_interrupt_asserted, write_sr_L2
        cmpw    cr6, base_disp, immed_data
        bgt     cr6, write_sr_L5
write_sr_L2:
        cmpwi   cr6, immed_data, 0
        lwz     immed_data, 0x1CC(EmulatorStatePtr)
        rlwinm  immed_data, immed_data, 0, 23, 23       // immed_data = immed_data[8] << 8
        bne     cr6, write_sr_L3
        cmpwi   cr6, immed_data, 0
        beq     cr6, write_sr_L3
        mr      base_disp, addr
        li      addr, 1
        li      zero, 13
        mcrf    cr6, cr0                                // cr6 = cr0
        sc
        li      zero, 0
        mcrf    cr0, cr6                                // cr0 = cr6
        mr      addr, base_disp
write_sr_L3:
        beqlr   cr7
write_sr_L4:
        ori     base_disp, code_ptr, stack_pointer_slots - cb  // slot of the stack pointer in use until now
        rlwimi  base_disp, sr_and_flags, 28, 30, 31     // base_disp[1:0] = sr_and_flags[5:4]
        rlwimi  sr_and_flags, data, 24, 24, 27          // new T1, T0, S, M
        lbz     immed_data, 0(base_disp)
        mtcrf   0x02, sr_and_flags                      // cr6 = sr_and_flags[7:4]
        rlwimi  base_disp, data, 20, 30, 31             // slot of the stack pointer to use from now on
        crxor   4*cr6+eq, cr_supervisor, 4*cr6+eq       // cr6.eq = cr_supervisor ^ cr6.eq
        lbz     base_disp, 0(base_disp)
        cror    cr_special_event_pending, cr_special_event_pending, 4*cr6+lt  // T1 set: trace
        stwx    a7, EmulatorStatePtr, immed_data        // save the old stack pointer
        cror    cr_special_event_pending, cr_special_event_pending, 4*cr6+gt  // T0 set: trace
        lwzx    a7, EmulatorStatePtr, base_disp         // load the new one
        bnelr   cr6
        crnot   cr_supervisor, cr_supervisor            // S changed
        blr
write_sr_L5:
        lbz     base_disp, 112(EmulatorStatePtr)
        cmpwi   cr6, base_disp, 128
        bge     cr6, write_sr_L6
        crset   cr_interrupt_pending
        crset   cr_special_event_pending
        beqlr   cr7
        b       write_sr_L4
write_sr_L6:
        mflr    base_disp
        bl      kcall_prioritize_interrupts
        mtlr    base_disp
        lbz     base_disp, interrupt_level(EmulatorStatePtr)
        cmpw    cr6, base_disp, immed_data
        cror    cr_interrupt_pending, cr_interrupt_pending, 4*cr6+gt  // cr_interrupt_pending = cr_interrupt_pending | cr6.gt
        cror    cr_special_event_pending, cr_special_event_pending, 4*cr6+gt  // cr_special_event_pending = cr_special_event_pending | cr6.gt
        beqlr   cr7
        b       write_sr_L4

// Offsets in the state block of the saved stack pointer for each value of
// the SR S and M bits: USP, USP, ISP, MSP.
stack_pointer_slots:
        .byte   0x48, 0x48, 0x4C, 0x50

// Reached from 1 dispatch table entry:
//     MOVE.W (An)+,SR
move_w_mem_sr:
        bfl     cr_supervisor, privilege_check_failed
        addi    a7, a7, 2

move_to_sr_from_addr:
        lhz     data, 0(addr)

// MOVE to SR, common part: data = the new SR.  write_sr takes the system
// byte; the condition codes are loaded here.
move_to_sr:
        lwz     base_disp, write_sr_handler(EmulatorStatePtr)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtctr   base_disp
        rlwinm  ccr_x, data, 25, 2, 2                   // X
        bfl     cr_supervisor, move_to_sr_user
        btctrl  cr_supervisor                           // supervisor: write_sr
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwinm  immed_data, data, 27, 2, 2              // immed_data = data[2] << 29
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwimi  immed_data, data, 28, 0, 0              // immed_data[31] = data[3]
        rlwinm  data, data, 29, 1, 2                    // data = data[1:0] << 29
        mtcrf   0x80, immed_data                        // N, Z
        mtxer   data                                    // V, C
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     MOVE.W Dn,SR
move_w_dn_sr:
        bfl     cr_supervisor, privilege_check_failed
        b       move_to_sr

// Reached from 8 dispatch table entries:
//     MOVE.W (An),SR
move_w_mem_sr_2:
        bfl     cr_supervisor, privilege_check_failed
        lhz     data, 0(addr)
        b       move_to_sr

// Reached from 11 dispatch table entries:
//     MOVE.W (d16,An),SR
//     MOVE.W (xxx).W,SR
//     MOVE.W (d16,PC),SR
//     MOVE.W #<data>,SR
move_w_ea_sr:
        bfl     cr_supervisor, privilege_check_failed
        lhz     data, 0(addr)
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        b       move_to_sr

// Reached from 8 dispatch table entries:
//     MOVE.W -(An),SR
move_w_mem_sr_3:
        li      data, -2

// Reached from 17 dispatch table entries:
//     MOVE.W (d8,An,Xn),SR
//     MOVE.W (An)+,SR
//     MOVE.W (xxx).L,SR
//     MOVE.W (d8,PC,Xn),SR
move_w_mem_sr_4:
        mtctr   addr
        bfl     cr_supervisor, privilege_check_failed
        ori     rtn_addr, code_ptr, move_to_sr_from_addr - cb
        bctr

// Reached from 1 dispatch table entry:
//     ANDI.W #<data>,SR
andi_w_imm_sr:
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        mtctr   base_disp
        bfl     cr_supervisor, andi_to_sr_user
        and     data, data, prefetch_data
        lhau    rtn_addr, 2(pc)                         // rtn_addr = next word: pc += 2, load the word there
        bctrl

// Reached from 1 dispatch table entry:
//     ANDI.B #<data>,CCR
andi_b_imm_ccr:
        mtcrf   0x01, prefetch_data                     // cr7 = prefetch_data[3:0]
        mfxer   data
        rlwinm  immed_data, prefetch_data, 29, 1, 2     // immed_data = prefetch_data[1:0] << 29
        crand   eq, eq, 4*cr7+gt                        // cr0.eq = cr0.eq & cr7.gt
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        and     data, data, immed_data
        crand   lt, lt, 4*cr7+lt                        // cr0.lt = cr0.lt & cr7.lt
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwinm  immed_data, prefetch_data, 25, 2, 2     // immed_data = prefetch_data[4] << 29
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        mtxer   data
        and     ccr_x, ccr_x, immed_data
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 1 dispatch table entry:
//     EORI.W #<data>,SR
eori_w_imm_sr:
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        mtctr   base_disp
        bfl     cr_supervisor, ori_eori_to_sr_user
        xor     data, data, prefetch_data
        lhau    rtn_addr, 2(pc)                         // rtn_addr = next word: pc += 2, load the word there
        bctrl

// Reached from 1 dispatch table entry:
//     EORI.B #<data>,CCR
eori_b_imm_ccr:
        mtcrf   0x01, prefetch_data                     // cr7 = prefetch_data[3:0]
        mfxer   data
        rlwinm  immed_data, prefetch_data, 29, 1, 2     // immed_data = prefetch_data[1:0] << 29
        crxor   eq, eq, 4*cr7+gt                        // cr0.eq = cr0.eq ^ cr7.gt
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        xor     data, data, immed_data
        crxor   lt, lt, 4*cr7+lt                        // cr0.lt = cr0.lt ^ cr7.lt
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwinm  immed_data, prefetch_data, 25, 2, 2     // immed_data = prefetch_data[4] << 29
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        mtxer   data
        xor     ccr_x, ccr_x, immed_data
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 1 dispatch table entry:
//     ORI.W #<data>,SR
ori_w_imm_sr:
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        mtctr   base_disp
        bfl     cr_supervisor, ori_eori_to_sr_user
        or      data, data, prefetch_data
        lhau    rtn_addr, 2(pc)                         // rtn_addr = next word: pc += 2, load the word there
        bctrl

// Reached from 1 dispatch table entry:
//     ORI.B #<data>,CCR
ori_b_imm_ccr:
        mtcrf   0x01, prefetch_data                     // cr7 = prefetch_data[3:0]
        mfxer   data
        rlwinm  immed_data, prefetch_data, 29, 1, 2     // immed_data = prefetch_data[1:0] << 29
        cror    eq, eq, 4*cr7+gt                        // cr0.eq = cr0.eq | cr7.gt
        rlwimi  disp_table, rtn_addr, 3, 13, 28         // DECODE1: disp_table[18:3] = opcode in rtn_addr
        or      data, data, immed_data
        cror    lt, lt, 4*cr7+lt                        // cr0.lt = cr0.lt | cr7.lt
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwinm  immed_data, prefetch_data, 25, 2, 2     // immed_data = prefetch_data[4] << 29
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        mtxer   data
        or      ccr_x, ccr_x, immed_data
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Throwaway frame: load the SR from it, discard it, and continue with the
// frame beneath.
rte_format_1:
        addi    a7, a7, 8
        bl      set_ccr

// ===========================================================================
// RTE
// ===========================================================================
// Reached through require_supervisor and handler slot +0x82C.  The frame
// format (bits 15:12 of the word at 6(a7)) selects one of sixteen
// handlers from the table at +0x830; each is entered with data = the
// stacked SR and addr = the stacked pc.
rte:
        lhz     data, 6(a7)                             // format / vector offset word
        mr      rtn_addr, EmulatorStatePtr
        rlwimi  rtn_addr, data, 22, 26, 29              // +0x830 + 4 * format
        lwz     rtn_addr, 0x830(rtn_addr)
        lhz     data, 0(a7)                             // stacked SR
        mtlr    rtn_addr
        lwz     addr, 2(a7)                             // stacked pc
        blrl

// Six-word frame: four more bytes to discard than format 0.
rte_format_2:
        addi    a7, a7, 4

// Pop the frame, load the SR and condition codes, and resume at the
// stacked pc.
rte_format_0:
        addi    a7, a7, 8
        bl      set_ccr
        lha     prefetch_data, 0(addr)
        mr      pc, addr
        rlwimi  disp_table, pc, 20, 11, 11              // odd address check
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

rte_bad_format:
        li      immed_data, 56                          // vector offset 0x38: format error
        b       take_exception

// Reached from 8 dispatch table entries:
//     MOVE.L An,USP
move_l_an_usp:
        lwz     rtn_addr, 0x874(EmulatorStatePtr)
        b       require_supervisor
move_l_an_usp_L1:
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        stw     data, saved_usp(EmulatorStatePtr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     MOVE.L USP,An
move_l_usp_an:
        lwz     rtn_addr, 0x870(EmulatorStatePtr)
        b       require_supervisor
move_l_usp_an_L1:
        mtctr   data
        lwz     data, saved_usp(EmulatorStatePtr)
        bctr

// MOVEC Rn,Rc (4E7B), through handler slot +0x87C.  The extension word in
// prefetch_data names the control register (low 12 bits) and the general
// register (high 4 bits).  movec_tables gives the control register's slot
// in the state block and the offset of the routine that stores it; the
// general register is read through reg_access_base_disp.  A control
// register with no table entry is an illegal instruction.
movec_to_control:
        rlwinm  data, prefetch_data, 0, 21, 28          // data = prefetch_data[10:3] << 3
        ori     rtn_addr, code_ptr, movec_tables - cb
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  rtn_addr, prefetch_data, 0, 29, 31      // rtn_addr[2:0] = prefetch_data[2:0]
        rlwimi  base_disp, prefetch_data, 24, 24, 27    // base_disp[7:4] = prefetch_data[15:12]
        rlwimi  rtn_addr, prefetch_data, 24, 28, 28     // rtn_addr[3] = prefetch_data[11]
        mtctr   base_disp
        lbz     addr, 16(rtn_addr)
        cmplwi  cr7, data, 0x0000
        add     addr, rtn_addr, addr
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        mtlr    addr
        mtcrf   0x02, sr_and_flags                      // cr6 = sr_and_flags[7:4]
        lbz     immed_data, 0(rtn_addr)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        beqctr  cr7
        b       movec_from_control_L1

// MOVEC Rc,Rn (4E7A), through handler slot +0x878.
movec_from_control:
        rlwinm  data, prefetch_data, 0, 21, 28          // data = prefetch_data[10:3] << 3
        ori     rtn_addr, code_ptr, movec_tables - cb
        ori     base_disp, code_ptr, reg_access_base_disp_L1 - cb
        rlwimi  rtn_addr, prefetch_data, 0, 29, 31      // rtn_addr[2:0] = prefetch_data[2:0]
        rlwimi  base_disp, prefetch_data, 24, 24, 27    // base_disp[7:4] = prefetch_data[15:12]
        rlwimi  rtn_addr, prefetch_data, 24, 28, 28     // rtn_addr[3] = prefetch_data[11]
        cmplwi  cr7, data, 0x0000
        lbz     addr, 32(rtn_addr)
        mtcrf   0x02, sr_and_flags                      // cr6 = sr_and_flags[7:4]
        add     addr, rtn_addr, addr
        lbz     immed_data, 0(rtn_addr)
        mtctr   addr
        mtlr    base_disp
        lwzx    base_disp, EmulatorStatePtr, immed_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        beqctr  cr7
movec_from_control_L1:
        lwz     rtn_addr, illegal_handler(EmulatorStatePtr)
        addi    pc, pc, -2
        b       take_illegal_instruction
        .long   0x4800000C
        ALIGN(16)

// Byte tables for MOVEC: for each control register number, the offset of
// its copy in the state block (0 = not implemented), followed by offsets
// of the code that reads or writes it.
movec_tables:
        .byte   0x58, 0x5C, 0x60, 0x00, 0x00, 0x00, 0x00, 0x00
        .byte   0x48, 0x54, 0x64, 0x50, 0x4C, 0x00, 0x00, 0x00
        .byte   0x60, 0x5F, 0x4E, 0xE5, 0xE4, 0xE3, 0xE2, 0xE1
        .byte   0x5C, 0x3F, 0x5A, 0x25, 0x30, 0xDB, 0xDA, 0xD9
        .byte   0x94, 0x93, 0x8E, 0xE5, 0xE4, 0xE3, 0xE2, 0xE1
        .byte   0x90, 0x8F, 0x8E, 0x6D, 0x78, 0xDB, 0xDA, 0xD9
        bns     cr6, movec_tables_L1
        mr      a7, base_disp
        b       movec_tables_L1
        bso     cr6, movec_tables_L1
        mr      a7, base_disp
        b       movec_tables_L1
        mr      vbr, base_disp
        b       movec_tables_L1
        lwz     data, dr_flush_vector(EmulatorStatePtr)
        mtctr   data
        btctrl  cr_dr_ready
        clrlwi  base_disp, base_disp, 30                // base_disp = base_disp & 0x00000003
        clrlwi  base_disp, base_disp, 29                // base_disp = base_disp & 0x00000007
movec_tables_L1:
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        stwx    base_disp, EmulatorStatePtr, immed_data
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
        bnslr   cr6
        mr      base_disp, a7
        blr
        bsolr   cr6
        mr      base_disp, a7
        blr
        clrlwi  base_disp, base_disp, 30                // base_disp = base_disp & 0x00000003
        clrlwi  base_disp, base_disp, 29                // base_disp = base_disp & 0x00000007
        blr

// Reached from 7 dispatch table entries:
//     MOVES.B Rn,-(An)
moves_b_rn_mem:
        li      data, -1

// MOVES.  Privileged; otherwise the move is an ordinary one - the source
// and destination function codes select nothing.  The routine in handler
// slot +0x824 is called first.
//
// Reached from 17 dispatch table entries:
//     MOVES.B Rn,(An)+
//     MOVES.B Rn,(d8,An,Xn)
//     MOVES.B Rn,(xxx).L
moves_b_rn_mem_2:
        bfl     cr_supervisor, take_privilege_violation
        mtctr   addr
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        ori     rtn_addr, code_ptr, moves_b_rn_mem_5_L1 - cb
        bctr

// Reached from 9 dispatch table entries:
//     MOVES.B Rn,(d16,An)
//     MOVES.B Rn,(xxx).W
moves_b_rn_mem_3:
        bfl     cr_supervisor, take_privilege_violation
        ori     rtn_addr, code_ptr, moves_b_rn_mem_5_L1 - cb
        b       moves_l_rn_mem_4_L2

// Reached from 1 dispatch table entry:
//     MOVES.B Rn,-(An)
moves_b_rn_mem_4:
        bfl     cr_supervisor, take_privilege_violation
        addi    a7, a7, -2

// Reached from 8 dispatch table entries:
//     MOVES.B Rn,(An)
moves_b_rn_mem_5:
        bfl     cr_supervisor, take_privilege_violation
        mr      immed_data, prefetch_data
