        mtlr    rtn_addr
        bctr
moves_l_rn_mem_4_L5:
        blr
moves_l_rn_mem_4_L6:
        mtctr   rtn_addr
        lwz     data, saved_dfc(EmulatorStatePtr)
        bctr
moves_l_rn_mem_4_L7:
