        mtlr    base_disp
        mtcrf   0x0F, immed_data                        // cr4..cr7 = immed_data[15:0]
        cror    4*cr4+lt, 4*cr4+lt, eq                  // cr4.lt = cr4.lt | cr0.eq
        blrl
        cmplw   cr6, data, rtn_addr                     // bounds the wrong way round ?
        blt     cr4, chk2_cmp2_l_mem_rn_3_L3
        slw     base_disp, base_disp, addr
        sraw    base_disp, base_disp, addr              // base_disp = base_disp >> addr (arithmetic)
chk2_cmp2_l_mem_rn_3_L3:
        cmplw   cr7, base_disp, data
        bgt     cr6, chk2_cmp2_l_mem_rn_3_L6
        cmplw   cr6, rtn_addr, base_disp
        bgt     cr7, chk2_cmp2_l_mem_rn_3_L7
chk2_cmp2_l_mem_rn_3_L4:
        crand   4*cr5+lt, 4*cr5+lt, 4*cr7+lt            // cr5.lt = cr5.lt & cr7.lt
        subfco. base_disp, data, base_disp              // base_disp = base_disp - data
        addc    base_disp, data, base_disp
        blt     cr5, take_chk_exception                 // CHK2 and out of bounds
chk2_cmp2_l_mem_rn_3_L5:
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
chk2_cmp2_l_mem_rn_3_L6:
        cmplw   cr6, rtn_addr, base_disp
        bge     cr7, chk2_cmp2_l_mem_rn_3_L4
chk2_cmp2_l_mem_rn_3_L7:
        crand   4*cr5+lt, 4*cr5+lt, 4*cr6+lt            // cr5.lt = cr5.lt & cr6.lt
        subfco. rtn_addr, base_disp, rtn_addr           // rtn_addr = rtn_addr - base_disp
        addc    rtn_addr, base_disp, rtn_addr
        bge     cr5, chk2_cmp2_l_mem_rn_3_L5

take_chk_exception:
        li      immed_data, 0x2018                      // format 2, vector offset 0x18: CHK

// Raise an exception whose frame carries the address of the instruction
// (format 2).  pc has moved on by an amount that depends on the
// addressing mode, so the start of the instruction is found by searching
// backwards from pc, up to seven words, for the opcode word - which is
// recovered from disp_table.
take_format2_exception:
        li      base_disp, 7
        mr      addr, pc                                // start at pc
        mtctr   base_disp
        rlwinm  data, disp_table, 29, 16, 31            // the opcode of this instruction
take_format2_exception_L1:
        lhzu    base_disp, -2(addr)                     // step back one word
        cmpw    cr6, data, base_disp
        bdnzf   4*cr6+eq, take_format2_exception_L1

raise_format2:
        lwz     rtn_addr, format2_handler(EmulatorStatePtr)
        crset   4*cr7+so                                // ask take_exception to return for the extra longword
        mtlr    rtn_addr
        blrl

// Reached from 16 dispatch table entries:
//     TRAP #<q>
trap_q:
        lwz     rtn_addr, format2_handler(EmulatorStatePtr)
        crclr   4*cr7+so
        mtlr    rtn_addr
        blrl

// Default for handler slot +0x810: push a format 2 frame.  Entered with
// addr = the instruction address for the frame, and cr7.so saying whether
// there is one (TRAP #n comes here with it clear, for a format 0 frame).
format2_exception:
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        rlwinm  base_disp, sr_and_flags, 2, 23, 23      // base_disp = sr_and_flags[6] << 8
        rlwinm  sr_and_flags, sr_and_flags, 0, 26, 23   // sr_and_flags = sr_and_flags & 0xFFFFFF3F
        or      sr_and_flags, sr_and_flags, base_disp
        bl      take_exception_pc_set
        stwu    addr, -4(a7)                            // the extra longword: address of the instruction
        blr

// Reached from 20 dispatch table entries:
//     TRAPHI #<data>.W
//     TRAPHI #<data>.L
//     TRAPLS #<data>.W
//     TRAPLS #<data>.L
//     TRAPCC #<data>.W
//     TRAPCC #<data>.L
//     ... and 14 more forms
trapcc:
        ori     base_disp, code_ptr, condition_truth_table - cb

// TRAPcc.  The condition is looked up rather than computed: the word for
// the condition in condition_truth_table has one bit for each combination
// of the flags, and the flags, gathered from the XER and cr0 into a
// five-bit number, select it.
//
// Reached from 9 dispatch table entries:
//     TRAPHI
//     TRAPLS
//     TRAPCC
//     TRAPCS
//     TRAPVC
//     TRAPGE
//     ... and 3 more forms
trapcc_2:
        mfxer   immed_data                              // C and V ...
        rlwinm  data, disp_table, 23, 26, 29            // data = disp_table[14:11] << 2
        mfcr    rtn_addr                                // ... N and Z
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwnm   data, data, immed_data, 31, 31          // the truth bit for this combination
        cmplwi  cr6, data, 0x0000
        bne     cr6, trapv_trapvs_L2
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 5 dispatch table entries:
//     TRAPT #<data>.L
//     TRAPNE #<data>.L
//     TRAPEQ #<data>.L
//     TRAPPL #<data>.L
//     TRAPMI #<data>.L
trapcc_3:
        addi    pc, pc, 2

// Reached from 5 dispatch table entries:
//     TRAPT #<data>.W
//     TRAPNE #<data>.W
//     TRAPEQ #<data>.W
//     TRAPPL #<data>.W
//     TRAPMI #<data>.W
trapcc_4:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Reached from 5 dispatch table entries:
//     TRAPT
//     TRAPNE
//     TRAPEQ
//     TRAPPL
//     TRAPMI
trapcc_5:
        bso     cr7, trapv_trapvs_L2
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 2 dispatch table entries:
//     TRAPV
//     TRAPVS
trapv_trapvs:
        rlwinm  data, data, 8, 24, 27                   // data = data[31:28] << 4
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        mtcrf   0x02, data                              // cr6 = data[7:4]
        bgt     cr6, trapv_trapvs_L1
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
trapv_trapvs_L1:
        clrrwi  disp_table, disp_table, 5               // disp_table = disp_table & 0xFFFFFFE0
trapv_trapvs_L2:
        li      addr, 0x602
        oris    addr, addr, 0x0004
        rlwnm   addr, addr, disp_table, 24, 31          // addr = rotl(addr, disp_table) & 0x000000FF
        subf    addr, addr, pc                          // addr = pc - addr
        li      immed_data, 0x201C
        b       raise_format2

// Reached from 8 dispatch table entries:
//     MOVE.W CCR,Dn
move_w_ccr_dn:
        rlwinm  data, ccr_x, 7, 27, 27                  // data = ccr_x[29] << 4
move_w_ccr_dn_L1:
        mfcr    immed_data
        mtctr   addr
        rlwimi  data, immed_data, 4, 28, 28             // data[3] = immed_data[31]
        rlwimi  data, immed_data, 5, 29, 29             // data[2] = immed_data[29]
        mfxer   immed_data
        rlwimi  data, immed_data, 3, 30, 31             // data[1:0] = immed_data[30:29]
        bctr

// Reached from 9 dispatch table entries:
//     MOVE.W CCR,(d16,An)
//     MOVE.W CCR,(xxx).W
move_w_ccr_mem:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Reached from 8 dispatch table entries:
//     MOVE.W CCR,(An)
// Continuation (via rtn_addr) of 17 dispatch table entries:
//     MOVE.W CCR,(An)+
//     MOVE.W CCR,(d8,An,Xn)
//     MOVE.W CCR,(xxx).L
move_w_ccr_mem_2:
        rlwinm  data, ccr_x, 7, 27, 27                  // data = ccr_x[29] << 4
move_w_ccr_mem_2_L1:
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mfcr    immed_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwimi  data, immed_data, 4, 28, 28             // data[3] = immed_data[31]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwimi  data, immed_data, 5, 29, 29             // data[2] = immed_data[29]
        mfxer   immed_data
        rlwimi  data, immed_data, 3, 30, 31             // data[1:0] = immed_data[30:29]
        sth     data, 0(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 11 dispatch table entries:
//     MOVE.W (d16,An),CCR
//     MOVE.W (xxx).W,CCR
//     MOVE.W (d16,PC),CCR
//     MOVE.W #<data>,CCR
move_w_ea_ccr:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Reached from 24 dispatch table entries:
//     MOVE.W Dn,CCR
//     MOVE.W (An),CCR
//     MOVE.W -(An),CCR
// Continuation (via rtn_addr) of 18 dispatch table entries:
//     MOVE.W (An)+,CCR
//     MOVE.W (d8,An,Xn),CCR
//     MOVE.W (xxx).L,CCR
//     MOVE.W (d8,PC,Xn),CCR
move_w_mem_ccr:
        rlwinm  immed_data, data, 27, 2, 2              // immed_data = data[2] << 29
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        rlwinm  ccr_x, data, 25, 2, 2                   // ccr_x = data[4] << 29
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        rlwimi  immed_data, data, 28, 0, 0              // immed_data[31] = data[3]
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        rlwinm  data, data, 29, 1, 2                    // data = data[1:0] << 29
        mtcrf   0x80, immed_data                        // cr0 = immed_data[31:28]
        mtxer   data
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     CAS.B Dc,Du,(d16,An)
cas_b_mem:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        lbzux   data, addr, base_disp
        b       cas_b_mem_3_L1

// Reached from 9 dispatch table entries:
//     CAS.B Dc,Du,(An)
//     CAS.B Dc,Du,(xxx).W
// Continuation (via rtn_addr) of 8 dispatch table entries:
//     CAS.B Dc,Du,(An)+
cas_b_mem_2:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// CAS.  immed_data is the extension word: Dc in bits 2:0, Du in bits 8:6.
// The operand is compared with Dc as CMP would; if they are equal Du is
// stored in the operand, otherwise the operand is loaded into Dc.  The
// routine in handler slot +0x884 (+0x888 and +0x88C for the other sizes)
// is called first.  Only the long form with an aligned address
// (cas_l_mem_3_L3) uses lwarx and stwcx. to make the exchange atomic.
//
// Continuation (via rtn_addr) of 9 dispatch table entries:
//     CAS.B Dc,Du,(d8,An,Xn)
//     CAS.B Dc,Du,(xxx).L
cas_b_mem_3:
        lbz     data, 0(addr)
cas_b_mem_3_L1:
        lwz     base_disp, cas_b_handler(EmulatorStatePtr)
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        mtlr    base_disp
        rlwimi  rtn_addr, immed_data, 30, 25, 27        // rtn_addr[6:4] = immed_data[8:6]
        blrl
cas_b_mem_3_L2:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, immed_data, 4, 25, 27        // base_disp[6:4] = immed_data[2:0]
        mtctr   base_disp
        slwi    data, data, 24
        blrl
        slwi    immed_data, base_disp, 24
        subfco. data, immed_data, data                  // compare; the flags are CMP's
        addc    data, immed_data, data
        rlwimi  base_disp, data, 8, 24, 31              // base_disp[7:0] = data[31:24]
        bnelr                                           // different: Dc = operand
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        stb     rtn_addr, 0(addr)                       // equal: operand = Du
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     CAS.W Dc,Du,(d16,An)
cas_w_mem:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        lhzux   data, addr, base_disp
        b       cas_w_mem_3_L1

// Reached from 9 dispatch table entries:
//     CAS.W Dc,Du,(An)
//     CAS.W Dc,Du,(xxx).W
// Continuation (via rtn_addr) of 8 dispatch table entries:
//     CAS.W Dc,Du,(An)+
cas_w_mem_2:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Continuation (via rtn_addr) of 9 dispatch table entries:
//     CAS.W Dc,Du,(d8,An,Xn)
//     CAS.W Dc,Du,(xxx).L
cas_w_mem_3:
        lhz     data, 0(addr)
cas_w_mem_3_L1:
        lwz     base_disp, cas_w_handler(EmulatorStatePtr)
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        mtlr    base_disp
        rlwimi  rtn_addr, immed_data, 30, 25, 27        // rtn_addr[6:4] = immed_data[8:6]
        blrl
cas_w_mem_3_L2:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, immed_data, 4, 25, 27        // base_disp[6:4] = immed_data[2:0]
        mtctr   base_disp
        slwi    data, data, 16
        blrl
        slwi    immed_data, base_disp, 16
        subfco. data, immed_data, data                  // data = data - immed_data
        addc    data, immed_data, data
        rlwimi  base_disp, data, 16, 16, 31             // base_disp[15:0] = data[31:16]
        bnelr
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        sth     rtn_addr, 0(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Reached from 8 dispatch table entries:
//     CAS.L Dc,Du,(d16,An)
cas_l_mem:
        lhau    base_disp, 2(pc)                        // base_disp = next word: pc += 2, load the word there
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        lwzux   data, addr, base_disp
        b       cas_l_mem_3_L1

// Reached from 9 dispatch table entries:
//     CAS.L Dc,Du,(An)
//     CAS.L Dc,Du,(xxx).W
// Continuation (via rtn_addr) of 8 dispatch table entries:
//     CAS.L Dc,Du,(An)+
cas_l_mem_2:
        mr      immed_data, prefetch_data
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// Continuation (via rtn_addr) of 9 dispatch table entries:
//     CAS.L Dc,Du,(d8,An,Xn)
//     CAS.L Dc,Du,(xxx).L
cas_l_mem_3:
        lwz     data, 0(addr)
cas_l_mem_3_L1:
        lwz     base_disp, cas_l_handler(EmulatorStatePtr)
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        mtlr    base_disp
        rlwimi  rtn_addr, immed_data, 30, 25, 27        // rtn_addr[6:4] = immed_data[8:6]
        blrl
cas_l_mem_3_L2:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, immed_data, 4, 25, 27        // base_disp[6:4] = immed_data[2:0]
        mtctr   base_disp
        clrlwi. base_disp, addr, 30                     // base_disp = addr & 0x00000003
        beq     cas_l_mem_3_L3
        blrl
        subfco. data, base_disp, data                   // data = data - base_disp
        addc    base_disp, base_disp, data
        bnelr
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        stw     rtn_addr, 0(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event
cas_l_mem_3_L3:
        blrl
cas_l_mem_3_L4:
        lwarx   data, 0, addr
        cmplw   base_disp, data
        bne     cas_l_mem_3_L5
        stwcx.  rtn_addr, 0, addr
        bne     cas_l_mem_3_L4
cas_l_mem_3_L5:
        subfco. data, base_disp, data                   // data = data - base_disp
        addc    base_disp, base_disp, data
        bnelr
        b       fetch

// CAS2.  The table entry has loaded the routine from cas2_w_handler or
// cas2_l_handler into rtn_addr and it is called first.  The two extension
// words are read together as one long word: Rn1, Du1 and Dc1 in bits
// 31:28, 24:22 and 18:16, and Rn2, Du2 and Dc2 in bits 15:12, 8:6 and 2:0.
// Both operands are compared with their Dc; if both are equal both Du are
// stored, otherwise both operands are loaded into the Dc registers.
//
// Reached from 2 dispatch table entries:
//     CAS2.W Dc1:Dc2,Du1:Du2,(Rn1):(Rn2)
//     CAS2.L Dc1:Dc2,Du1:Du2,(Rn1):(Rn2)
cas2:
        mtlr    rtn_addr
        mtcrf   0x0F, disp_table                        // the opcode: cr4.so tells CAS2.L from CAS2.W
        lwz     prefetch_data, 0(pc)                    // both extension words
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        rlwimi  rtn_addr, prefetch_data, 20, 25, 27     // rtn_addr[6:4] = prefetch_data[18:16]
        blrl
cas2_L1:
        mtlr    rtn_addr
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, prefetch_data, 8, 24, 27     // base_disp[7:4] = prefetch_data[31:28]
        mtctr   base_disp
        blrl
        mr      addr, base_disp
        mr      data, rtn_addr
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        rlwimi  rtn_addr, prefetch_data, 4, 25, 27      // rtn_addr[6:4] = prefetch_data[2:0]
        mtlr    rtn_addr
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, prefetch_data, 24, 24, 27    // base_disp[7:4] = prefetch_data[15:12]
        mtctr   base_disp
        blrl
        mr      immed_data, base_disp
        mr      base_disp, prefetch_data
        mr      prefetch_data, rtn_addr
        ori     rtn_addr, code_ptr, reg_access_rtn_addr - cb
        rlwimi  rtn_addr, base_disp, 30, 25, 27         // rtn_addr[6:4] = base_disp[8:6]
        mtlr    rtn_addr
        ori     rtn_addr, code_ptr, reg_access_base_disp - cb
        rlwimi  rtn_addr, base_disp, 14, 25, 27         // rtn_addr[6:4] = base_disp[24:22]
        mtctr   rtn_addr
        blrl
        mtlr    base_disp
        mtctr   rtn_addr
        bns     cr4, cas2_L3
        lwz     base_disp, 0(addr)
        lwz     rtn_addr, 0(immed_data)
        subfco. base_disp, data, base_disp              // base_disp = base_disp - data
        addc    base_disp, data, base_disp
        bne     cas2_L5
        subfco. rtn_addr, prefetch_data, rtn_addr       // rtn_addr = rtn_addr - prefetch_data
        addc    rtn_addr, prefetch_data, rtn_addr
        bne     cas2_L5
        mflr    base_disp
        mfctr   rtn_addr
        stw     base_disp, 0(addr)
        stw     rtn_addr, 0(immed_data)
cas2_L2:
        lhau    prefetch_data, 4(pc)                    // PREFETCH: pc += 4, load the word there
        b       fetch
cas2_L3:
        lhz     base_disp, 0(addr)
        lhz     rtn_addr, 0(immed_data)
        slwi    base_disp, base_disp, 16
        slwi    rtn_addr, rtn_addr, 16
        rlwimi  data, data, 16, 0, 31                   // data = (data & ~0xFFFFFFFF) | (rotl(data, 16) & 0xFFFFFFFF)
        rlwimi  prefetch_data, prefetch_data, 16, 0, 31  // prefetch_data = (prefetch_data & ~0xFFFFFFFF) | (rotl(prefetch_data, 16) & 0xFFFFFFFF)
        rlwimi  base_disp, data, 0, 16, 31              // base_disp[15:0] = data[15:0]
        rlwimi  rtn_addr, prefetch_data, 0, 16, 31      // rtn_addr[15:0] = prefetch_data[15:0]
        subfco. base_disp, data, base_disp              // base_disp = base_disp - data
        addc    base_disp, data, base_disp
        bne     cas2_L4
        subfco. rtn_addr, prefetch_data, rtn_addr       // rtn_addr = rtn_addr - prefetch_data
        addc    rtn_addr, prefetch_data, rtn_addr
        bne     cas2_L4
        mflr    base_disp
        mfctr   rtn_addr
        sth     base_disp, 0(addr)
        sth     rtn_addr, 0(immed_data)
        b       cas2_L2
cas2_L4:
        rlwimi  base_disp, base_disp, 16, 0, 31         // base_disp = (base_disp & ~0xFFFFFFFF) | (rotl(base_disp, 16) & 0xFFFFFFFF)
        rlwimi  rtn_addr, rtn_addr, 16, 0, 31           // rtn_addr = (rtn_addr & ~0xFFFFFFFF) | (rotl(rtn_addr, 16) & 0xFFFFFFFF)
cas2_L5:
        lwz     prefetch_data, 0(pc)
        ori     data, code_ptr, reg_access_rtn_addr_L1 - cb
        rlwimi  data, prefetch_data, 4, 25, 27          // data[6:4] = prefetch_data[2:0]
        mtctr   data
        ori     data, code_ptr, reg_access_base_disp_L1 - cb
        rlwimi  data, prefetch_data, 20, 25, 27         // data[6:4] = prefetch_data[18:16]
        mtlr    data
        lhau    prefetch_data, 4(pc)                    // PREFETCH: pc += 4, load the word there
        bctr

// Reached from 8 dispatch table entries:
//     TAS.B Dn
tas_b_dn:
        mtctr   addr
        addco   zero, zero, zero                        // V=0, C=0
        bctrl
        slwi.   data, base_disp, 24
        ori     base_disp, base_disp, 0x0080
        blr

// Reached from 9 dispatch table entries:
//     TAS.B (d16,An)
//     TAS.B (xxx).W
tas_b_mem:
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there

// TAS on memory: N and Z from the byte, then bit 7 set.  The routine in
// tas_handler is called first.  The two accesses are not made atomic.
//
// Reached from 8 dispatch table entries:
//     TAS.B (An)
// Continuation (via rtn_addr) of 17 dispatch table entries:
//     TAS.B (An)+
//     TAS.B (d8,An,Xn)
//     TAS.B (xxx).L
tas_b_mem_2:
        lwz     rtn_addr, tas_handler(EmulatorStatePtr)
        mtlr    rtn_addr
        blrl
tas_b_mem_2_L1:
        lbz     data, 0(addr)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        slwi.   immed_data, data, 24
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        ori     data, data, 0x0080
        addco   zero, zero, zero                        // V=0, C=0
        stb     data, 0(addr)
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// ===========================================================================
// Special event processing
// ===========================================================================
// Every emulation routine ends with DISPATCH, which falls through to here
// instead of entering the next instruction when cr_special_event_pending is
// set.  At this point pc and prefetch_data already describe the next
// instruction and disp_table addresses its dispatch table entry.
// The events, in the order they are tested:
// odd pc              -> address error exception
// trace pending       -> trace exception
// interrupt pending   -> interrupt exception, if its level beats the mask
// test-mode flags     -> debugging / profiling hooks
// SR T1/T0 set        -> arrange a trace exception after the next instruction
// The first thing done is an indirect call through a hook in the emulator
// state, which normally points straight back to special_event_continue.
process_special_event:
        lwz     rtn_addr, special_event_hook(EmulatorStatePtr)  // hook; normally special_event_continue
        rlwimi  sr_and_flags, pc, 9, 22, 22             // flag_odd_pc = low bit of pc
        mtlr    rtn_addr
        mtcrf   0x0F, sr_and_flags                      // cr4..cr7 = flag byte and SR byte of sr_and_flags
        crmove  cr_special_event_pending, 4*cr5+gt      // pending = "other event" flag (re-evaluated below)
        mtctr   disp_table                              // CTR = dispatch entry of the next instruction
        blrl

special_event_continue:
        beq     cr5, take_address_error                 // odd pc
        bso     cr5, take_trace_exception               // trace pending from the previous instruction
        cror    4*cr5+so, 4*cr6+lt, 4*cr6+gt            // trace needed if T1 or T0
        bl      check_interrupt                         // look for a pending interrupt
        btl     cr_interrupt_pending, take_interrupt
        bgt     cr5, test_mode_events
        bnsctr  cr5                                     // nothing left to do: run the instruction

// The next instruction is to be traced.  Remember where it starts and keep
// the special event pending so that control comes back here once it has
// run.  With T1 (trace all) that is unconditional; with T0 (trace on change
// of flow) the opcode is examined and trace_pending is only left set for
// instructions that change the flow of control.
arm_trace:
        crset   cr_special_event_pending
        addi    data, pc, -2                            // pc is 2 past the instruction
        stw     data, trace_pc(EmulatorStatePtr)
        ori     sr_and_flags, sr_and_flags, 0x0100      // flag_trace_pending
        bltctr  cr6                                     // T1: trace every instruction
        rlwinm  data, disp_table, 29, 16, 31            // data = the opcode about to run
        li      immed_data, 0xA40
        andc    immed_data, data, immed_data            // immed_data = data & ~immed_data
        cmpwi   cr7, immed_data, 60
        beqctr  cr7
        li      immed_data, 63
        andc    immed_data, data, immed_data            // immed_data = data & ~immed_data
        cmpwi   cr7, immed_data, 0x46C0
        beqctr  cr7
        li      immed_data, 0xFFF
        andc    immed_data, data, immed_data            // immed_data = data & ~immed_data
        cmpwi   cr7, immed_data, 0x6000
        beq     cr7, arm_trace_L2
        bgt     cr7, arm_trace_L1
        cmpwi   cr7, data, 0x4E73
        blt     cr7, arm_trace_L1
        cmpwi   cr7, data, 0x4E75
        blectr  cr7
        cmpwi   cr7, data, 0x4E77
        beqctr  cr7
        li      immed_data, 127
        andc    immed_data, data, immed_data            // immed_data = data & ~immed_data
        cmpwi   cr7, immed_data, 0x4E80
        beqctr  cr7
        li      immed_data, 0xF07
        andc    immed_data, data, immed_data            // immed_data = data & ~immed_data
        cmpwi   cr7, immed_data, 0x50C8
        bne     cr7, arm_trace_L1
        ori     base_disp, code_ptr, reg_access_base_disp - cb
        rlwimi  base_disp, data, 4, 25, 27              // base_disp[6:4] = data[2:0]
        mtlr    base_disp
        blrl
        clrlwi  base_disp, base_disp, 16                // base_disp = base_disp & 0x0000FFFF
        cmpwi   cr7, base_disp, 0
        xori    data, data, 0x0100
        bne     cr7, arm_trace_L3
arm_trace_L1:
        xori    sr_and_flags, sr_and_flags, 0x0100
        bctr
arm_trace_L2:
        cmpwi   cr7, data, 0x61FF
        blectr  cr7
arm_trace_L3:
        ori     base_disp, code_ptr, condition_truth_table - cb
        mfxer   immed_data
        rlwinm  data, data, 26, 26, 29                  // data = data[11:8] << 2
        mfcr    rtn_addr
        rlwinm  immed_data, immed_data, 3, 30, 31       // immed_data = immed_data[30:29]
        lwzx    data, base_disp, data
        rlwimi  immed_data, rtn_addr, 5, 27, 29         // immed_data[4:2] = rtn_addr[31:29]
        rlwnm   data, data, immed_data, 31, 31          // data = rotl(data, immed_data) & 0x00000001
        rlwimi  sr_and_flags, data, 8, 23, 23           // sr_and_flags[8] = data[0]
        bctr

take_trace_exception:
        cror    cr_special_event_pending, cr_special_event_pending, cr_interrupt_pending  // cr_special_event_pending = cr_special_event_pending | cr_interrupt_pending
        lwz     addr, trace_pc(EmulatorStatePtr)
        crset   4*cr7+so
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        li      immed_data, 0x2024                      // format 2, vector offset 0x24 (trace)
        bl      take_exception_sr_built
        stwu    addr, -4(a7)                            // format 2 carries the address of the traced instruction
        blr

// Take the pending interrupt if its level is above the SR mask (level 7 is
// not maskable).  Uses the autovector for the level, counts the interrupt,
// and if the master stack is active builds the 68020 "throwaway" frame on
// the interrupt stack as well.
take_interrupt:
        crclr   cr_interrupt_pending
        crclr   cr_dr_active
        lbz     base_disp, interrupt_level(EmulatorStatePtr)
        clrlwi  immed_data, sr_and_flags, 29            // immed_data = sr_and_flags & 0x00000007
        cmpw    cr7, base_disp, immed_data
        bgt     cr7, take_interrupt_L1
        cmpwi   cr7, base_disp, 7
        bnelr   cr7
take_interrupt_L1:
        li      data, 192                               // 0xC0 + 4*level: per-level interrupt counter in the state block
        rlwimi  data, base_disp, 2, 27, 29              // data[4:2] = base_disp[2:0]
        lwzx    base_disp, EmulatorStatePtr, data
        xori    immed_data, data, 0x00A0                // 0x60 + 4*level: autovector offset
        addi    base_disp, base_disp, 1
        stwx    base_disp, EmulatorStatePtr, data
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        crmove  4*cr7+so, 4*cr6+so
        rlwimi  sr_and_flags, immed_data, 30, 29, 31    // SR interrupt mask = level
        bl      take_exception_sr_built
        sthu    data, -8(a7)                            // push SR
        stw     pc, 2(a7)                               // push PC
        sth     immed_data, 6(a7)                       // push format/vector word
        stw     a7, saved_msp(EmulatorStatePtr)
        rlwinm  sr_and_flags, sr_and_flags, 0, 28, 26   // clear SR M bit
        lwz     a7, saved_isp(EmulatorStatePtr)
        ori     immed_data, immed_data, 0x1000          // format 1 (throwaway) for the second frame
        rlwimi  data, sr_and_flags, 8, 16, 23           // data[15:8] = sr_and_flags[7:0]
        blr

// The upper half of sr_and_flags holds debugging switches.  Each one that
// is set calls a small routine before the instruction runs.
test_mode_events:
        srwi    data, sr_and_flags, 16
        mtcrf   0x0F, data                              // cr4..cr7 = data[15:0]
        beql    cr4, check_prefetch_consistency         // bit 0x2000_0000: consistency checks
        bsol    cr7, count_instruction                  // bit 0x0001_0000: count instructions
        beql    cr7, count_opcode                       // bit 0x0002_0000: count instructions per opcode
        blt     cr4, exit_emulator
        ble     cr7, test_mode_events_L1
        lwz     addr, test_hook(EmulatorStatePtr)       // bit 0x0004_0000: call a hook
        lwz     data, test_hook_arg(EmulatorStatePtr)
        mtlr    addr
        cmplwi  cr7, addr, 0x0000
        bnelrl  cr7
test_mode_events_L1:
        mtcrf   0x0F, sr_and_flags                      // cr4..cr7 = sr_and_flags[15:0]
        cror    4*cr5+so, 4*cr6+lt, 4*cr6+gt            // cr5.so = cr6.lt | cr6.gt
        crmove  cr_special_event_pending, 4*cr5+gt
        bnsctr  cr5
        b       arm_trace

// Debugging aid: trap if prefetch_data, CTR or disp_table do not agree with
// the instruction stream at pc.
check_prefetch_consistency:
        lha     immed_data, -2(pc)
        lha     data, 0(pc)
        twi     24, zero, 0
        tw      24, data, prefetch_data
        mfctr   data
        tw      24, data, disp_table
        rlwimi  data, immed_data, 3, 13, 28             // data[18:3] = immed_data[15:0]
        tw      24, data, disp_table
        blr

count_instruction:
        lwz     data, instruction_count(EmulatorStatePtr)
        addi    data, data, 1
        stw     data, instruction_count(EmulatorStatePtr)
        blr

count_opcode:
        lwz     addr, opcode_counts(EmulatorStatePtr)
        rlwinm  immed_data, disp_table, 31, 14, 29      // immed_data = disp_table[18:3] << 2
        lwzx    data, addr, immed_data
        addi    data, data, 1
        stwx    data, addr, immed_data
        blr

// Trap to the kernel if a group 1 exception (bus or address error) happens
// while another is still being processed.
check_double_fault:
        rlwinm  data, sr_and_flags, 21, 31, 31          // data = sr_and_flags[11]
        twi     24, data, 0

// Build a 68020 format $B (long bus fault) frame for an address error.
take_address_error:
        rlwimi  disp_table, zero, 20, 11, 11            // clear the odd-pc marker in disp_table
        ori     sr_and_flags, sr_and_flags, 0x0800      // flag_group_1_active
        rlwinm  rtn_addr, sr_and_flags, 0, 20, 23       // rtn_addr = sr_and_flags[11:8] << 8
        ori     immed_data, zero, 0xB00C                // format $B, vector offset 0x00C (address error)
        crset   4*cr7+so
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        rlwinm  sr_and_flags, sr_and_flags, 0, 26, 21   // sr_and_flags = sr_and_flags & 0xFFFFFC3F
        bl      take_exception_pc_set
        addi    a7, a7, -84                             // the frame is 92 bytes in all
        lwz     addr, ecb_saved_flags(EmulatorStatePtr)
        ori     rtn_addr, rtn_addr, 0xE000
        rlwinm  addr, addr, 0, 28, 15                   // addr = addr & 0xFFFF000F
        sth     rtn_addr, 46(a7)
        stw     addr, 40(a7)
        rlwinm  rtn_addr, disp_table, 29, 16, 31        // rtn_addr = disp_table[18:3]
        lhz     addr, fault_cr(EmulatorStatePtr)
        sth     rtn_addr, 4(a7)
        sth     addr, 6(a7)
        addi    pc, pc, -2
        stw     pc, 28(a7)
        li      addr, 0x3000
        lwz     rtn_addr, trace_pc(EmulatorStatePtr)
        sth     addr, 2(a7)
        ori     addr, code_ptr, take_address_error_L1 - cb
        stw     rtn_addr, 24(a7)
        stw     addr, 80(a7)
        blr
take_address_error_L1:
        lhz     data, 188(EmulatorStatePtr)
        addi    pc, pc, -2
        mtcrf   0x08, data                              // cr4 = data[15:12]
        lha     immed_data, 0(pc)
        rlwimi  disp_table, pc, 20, 11, 11              // disp_table[20] = pc[0]
        bne     cr4, take_address_error_L2
        rlwimi  disp_table, immed_data, 3, 13, 28       // DECODE1: disp_table[18:3] = opcode in immed_data
take_address_error_L2:
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Called from special event processing.  Returns unless an interrupt above
// the current mask is requested; otherwise marks it pending.
check_interrupt:
        lwz     addr, 0x1D0(EmulatorStatePtr)
        clrlwi  immed_data, sr_and_flags, 29            // immed_data = sr_and_flags & 0x00000007
        lbz     base_disp, interrupt_level(EmulatorStatePtr)
        cmplw   cr7, addr, immed_data
        blelr   cr7
        bf_likely cr_interrupt_asserted, check_interrupt_L1
        cmplw   cr7, base_disp, addr
        bgtlr   cr7
check_interrupt_L1:
        mr      base_disp, addr
        addi    immed_data, EmulatorStatePtr, 0xAE0
        slwi    addr, addr, 2
        lwzx    addr, addr, immed_data
        lwz     immed_data, interrupt_counts(EmulatorStatePtr)
        addi    immed_data, immed_data, 1
        cror    cr_special_event_pending, cr_special_event_pending, cr_interrupt_pending  // cr_special_event_pending = cr_special_event_pending | cr_interrupt_pending
        stw     immed_data, interrupt_counts(EmulatorStatePtr)
        crset   4*cr7+so
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        li      immed_data, 0x2058
        rlwimi  sr_and_flags, base_disp, 0, 29, 31      // sr_and_flags[2:0] = base_disp[2:0]
        bl      take_exception_sr_built
        stwu    addr, -4(a7)
        blr

// Entered by the kernel when the processor takes an exception while the
// emulator context is running (its address is in ecb_handler).  On entry
// data (r4) holds ecb_handler_arg, the address of take_bus_error, and LR
// holds ecb_handler_return, the address of EmKernelTrapTable; the kernel
// has stored its description of the fault in the context block.
//
// Chooses where the emulator should resume - take_bus_error, or
// take_address_error if the fault was the deliberate jump past the
// dispatch table for an odd pc - stores that in ecb_pc, copies the fault
// details to where take_bus_error expects them, and returns.  Returning
// lands on slot 0 of the trap table, ReturnFromException, with r3 = 0.
native_exception_handler:
        rlwinm  addr, sr_and_flags, 21, 31, 31          // addr = sr_and_flags[11]
        twi     24, addr, 0
        mfcr    addr
        ori     sr_and_flags, sr_and_flags, 0x0800
        rlwimi  sr_and_flags, disp_table, 21, 22, 22    // sr_and_flags[9] = disp_table[20]
        mtcrf   0x0F, sr_and_flags                      // cr4..cr7 = sr_and_flags[15:0]
        stw     addr, fault_cr(EmulatorStatePtr)
        lwz     addr, ecb_pc(EmulatorStatePtr)
        bne     cr5, native_exception_handler_L1
        cmpw    cr7, disp_table, addr
        rlwimi  disp_table, zero, 20, 11, 11            // disp_table[20] = zero[0]
        bne     cr7, native_exception_handler_L1
        ori     data, code_ptr, take_address_error - cb
native_exception_handler_L1:
        stw     data, ecb_pc(EmulatorStatePtr)          // ecb_pc = where to resume
        lwz     data, ecb_saved_flags(EmulatorStatePtr)
        stw     addr, fault_pc(EmulatorStatePtr)
        mtcrf   0x0F, data                              // cr4..cr7 = data[15:0]
        stw     data, fault_saved_flags(EmulatorStatePtr)
        rlwinm  data, data, 0, 28, 15                   // data = data & 0xFFFF000F
        stw     data, ecb_saved_flags(EmulatorStatePtr)
        li      data, 9
        bns     cr6, native_exception_handler_L2
        lwz     addr, 0x17C(EmulatorStatePtr)
        lwz     data, 0x168(EmulatorStatePtr)
        stw     addr, 140(EmulatorStatePtr)
        lwz     addr, 0x16C(EmulatorStatePtr)
        stw     data, 144(EmulatorStatePtr)
        lwz     data, 0x164(EmulatorStatePtr)
        stw     addr, 148(EmulatorStatePtr)
        lwz     addr, 0x174(EmulatorStatePtr)
native_exception_handler_L2:
        stw     data, 132(EmulatorStatePtr)
        stw     addr, 136(EmulatorStatePtr)
        li      addr, 0
        blr

// Build a 68020 format $B (long bus fault) frame for a bus error.
take_bus_error:
        stw     data, fault_data(EmulatorStatePtr)
        stw     immed_data, fault_immed_data(EmulatorStatePtr)
        stw     base_disp, fault_base_disp(EmulatorStatePtr)
        mflr    data
        stw     data, fault_lr(EmulatorStatePtr)
        stw     sr_and_flags, fault_sr_and_flags(EmulatorStatePtr)
        ori     immed_data, zero, 0xB008                // format $B, vector offset 0x008 (bus error)
        crset   4*cr7+so
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        rlwinm  sr_and_flags, sr_and_flags, 0, 26, 21   // sr_and_flags = sr_and_flags & 0xFFFFFC3F
        bl      take_exception_pc_set
        addi    a7, a7, -84
        stw     addr, 48(a7)
        mfctr   addr
        stw     rtn_addr, 56(a7)
        rlwinm  rtn_addr, disp_table, 29, 16, 31        // rtn_addr = disp_table[18:3]
        stw     prefetch_data, 68(a7)
        sth     rtn_addr, 4(a7)
        stw     addr, 72(a7)
        lhz     rtn_addr, fault_cr(EmulatorStatePtr)
        lwz     addr, 136(EmulatorStatePtr)
        sth     rtn_addr, 6(a7)
        lwz     rtn_addr, 140(EmulatorStatePtr)
        stw     addr, 8(a7)
        lwz     addr, 144(EmulatorStatePtr)
        stw     rtn_addr, 12(a7)
        lwz     rtn_addr, 148(EmulatorStatePtr)
        stw     addr, 32(a7)
        lwz     addr, 132(EmulatorStatePtr)
        stw     rtn_addr, 36(a7)
        stw     rtn_addr, 16(a7)
        lwz     rtn_addr, fault_saved_flags(EmulatorStatePtr)
        stw     addr, 20(a7)
        slwi    addr, addr, 26
        stw     rtn_addr, 40(a7)
        rlwimi  addr, addr, 12, 25, 25                  // addr[6] = addr[26]
        mfxer   rtn_addr
        rlwimi  addr, addr, 9, 26, 27                   // addr[5:4] = addr[28:27]
        stw     pc, 28(a7)
        rlwimi  rtn_addr, rtn_addr, 8, 24, 24           // rtn_addr[7] = rtn_addr[31]
        rlwimi  addr, data, 21, 29, 29                  // addr[2] = data[13]
        sth     rtn_addr, 0(a7)
        ori     addr, addr, 0x0101
        sth     addr, 2(a7)
        addi    pc, pc, -2
        lwz     addr, trace_pc(EmulatorStatePtr)
        lhz     rtn_addr, 182(EmulatorStatePtr)
        stw     addr, 24(a7)
        lwz     addr, fault_data(EmulatorStatePtr)
        sth     rtn_addr, 44(a7)
        lwz     rtn_addr, fault_immed_data(EmulatorStatePtr)
        stw     addr, 52(a7)
        lwz     addr, fault_base_disp(EmulatorStatePtr)
        stw     rtn_addr, 60(a7)
        lwz     rtn_addr, fault_lr(EmulatorStatePtr)
        stw     addr, 64(a7)
        lwz     addr, fault_pc(EmulatorStatePtr)
        stw     rtn_addr, 76(a7)
        stw     addr, 80(a7)
        lwz     addr, fault_sr_and_flags(EmulatorStatePtr)
        rlwinm  rtn_addr, ccr_x, 2, 31, 31              // rtn_addr = ccr_x[30]
        ori     rtn_addr, rtn_addr, 0xE000
        rlwimi  rtn_addr, addr, 0, 20, 23               // rtn_addr[11:8] = addr[11:8]
        sth     rtn_addr, 46(a7)
        bflr    cr_dr_active
        lwz     rtn_addr, dr_fault_fixup_vector(EmulatorStatePtr)
        lwz     addr, fault_pc(EmulatorStatePtr)
        mtctr   rtn_addr
        bctr
take_bus_error_L1:
        lhz     immed_data, 54(a7)
        srwi    base_disp, immed_data, 12
