        crnand  gt, lt, eq                              // cr0.gt = ~(cr0.lt & cr0.eq)
        lwz     data, fault_data(EmulatorStatePtr)
        lwz     immed_data, fault_immed_data(EmulatorStatePtr)
        lwz     base_disp, fault_base_disp(EmulatorStatePtr)
