        stw     data, ecb_r4(EmulatorStatePtr)
        lwz     addr, ecb_handler_return(EmulatorStatePtr)
        lhz     data, 184(EmulatorStatePtr)
        mtlr    addr
        mfxer   addr
        rlwimi  addr, data, 0, 16, 31                   // addr[15:0] = data[15:0]
        mtcrf   0x03, data                              // cr6..cr7 = data[7:0]
        rlwimi  addr, data, 24, 0, 0                    // addr[31] = data[7]
        lhz     data, 186(EmulatorStatePtr)
        crmove  so, 4*cr7+so
        mtxer   addr
        mtcrf   0x07, data                              // cr5..cr7 = data[11:0]
        rlwimi  ccr_x, data, 30, 1, 1                   // ccr_x[30] = data[0]
        cror    cr_special_event_pending, cr_special_event_pending, 4*cr5+gt  // cr_special_event_pending = cr_special_event_pending | cr5.gt
        rlwimi  sr_and_flags, data, 0, 20, 23           // sr_and_flags[11:8] = data[11:8]
        rlwimi  disp_table, sr_and_flags, 11, 11, 11    // disp_table[20] = sr_and_flags[9]
        lwz     addr, 168(EmulatorStatePtr)
        cror    cr_special_event_pending, cr_special_event_pending, 4*cr5+so  // cr_special_event_pending = cr_special_event_pending | cr5.so
