        li      addr, 0
        mtcrf   0x4F, data                              // cr1 = data[27:24]; cr4 = data[15:12]; cr5 = data[11:8]; cr6 = data[7:4]; cr7 = data[3:0]
        rlwinm  sr_and_flags, sr_and_flags, 0, 21, 19   // sr_and_flags = sr_and_flags & 0xFFFFF7FF
        blr
        ALIGN(16)

// Dispatch table entries for unimplemented opcodes load a handler address
// from the state block into rtn_addr and branch here (vector 4), to
// take_fline (vector 11) or take_aline (vector 10).  The handler is
// normally take_exception, but can be replaced.
//
// Reached from 9977 dispatch table entries:
//     ILLEGAL
//     MOVE.B An,Dn (illegal)
//     MOVEA.B Dn,An (illegal)
//     MOVEA.B An,An (illegal)
//     MOVEA.B (An),An (illegal)
//     MOVEA.B (An)+,An (illegal)
//     ... and 1203 more forms
take_illegal_instruction:
        mtlr    rtn_addr
        li      immed_data, 16                          // vector offset 0x10: illegal instruction
        blrl
        ALIGN(32)

// Reached from 3588 dispatch table entries:
//     ILLEGAL
//     F-LINE cpID 0
//     F-LINE cpID 4
//     F-LINE cpID 5
//     F-LINE cpID 7
//     F-LINE cpID 6
//     ... and 29 more forms
take_fline:
        mtlr    rtn_addr
        li      immed_data, 44                          // vector offset 0x2C: line 1111 emulator
        blrl
        ALIGN(16)

take_aline:
        lwz     rtn_addr, aline_handler(EmulatorStatePtr)
        mtlr    rtn_addr
        li      immed_data, 40                          // vector offset 0x28: line 1010 emulator
        blrl

// ===========================================================================
// Exception entry
// ===========================================================================
// Build a 68K exception stack frame and continue at the handler named by
// the vector.
// On entry: immed_data = format/vector word for the frame (format in bits
// 15:12, vector offset in bits 11:0).  Entry at take_exception_sr_built is
// used by callers that have already put the SR high byte in data and set
// or cleared cr7.so themselves; cr7.so set means the caller wants control
// back (through LR) after the stack has been switched, so that it can push
// the extra words of a longer frame before the common SR/PC/format words.
take_exception:
        crclr   4*cr7+so                                // plain frame: no extra words
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = SR high byte, in place

take_exception_sr_built:
        addi    pc, pc, -2                              // pc = address of the instruction
        rlwinm  sr_and_flags, sr_and_flags, 0, 26, 22   // clear T1, T0 and trace_pending

take_exception_pc_set:
        rlwimi  data, ccr_x, 7, 27, 27                  // CCR bit 4 (X) from ccr_x
        mfcr    base_disp
        rlwimi  data, base_disp, 4, 28, 28              // CCR bit 3 (N) from cr0.lt
        rlwimi  data, base_disp, 5, 29, 29              // CCR bit 2 (Z) from cr0.eq
        mfxer   base_disp
        rlwimi  data, base_disp, 3, 30, 31              // CCR bits 1:0 (V, C) from XER[OV], XER[CA]

enter_supervisor:
        bt      cr_supervisor, push_exception_frame     // already in supervisor state
        mtcrf   0x02, sr_and_flags                      // cr6 = sr_and_flags[7:4]
        stw     a7, saved_usp(EmulatorStatePtr)         // save the user stack pointer
        lwz     a7, saved_isp(EmulatorStatePtr)         // assume the interrupt stack
        ori     sr_and_flags, sr_and_flags, 0x0020      // set SR S bit
        crset   cr_supervisor
        bns     cr6, push_exception_frame
        lwz     a7, saved_msp(EmulatorStatePtr)         // M bit set: the master stack instead

push_exception_frame:
        bsolrl  cr7                                     // let the caller push its extra frame words first
        sthu    data, -8(a7)                            // push SR
        stw     pc, 2(a7)                               // push PC
        rlwinm  base_disp, immed_data, 0, 20, 29        // vector offset
        lwzx    pc, vbr, base_disp                      // pc = handler address from the vector table
        sth     immed_data, 6(a7)                       // push format/vector word
        lha     prefetch_data, 0(pc)
        mtcrf   0x01, pc                                // cr7.so = low bit of the new pc
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bsol    cr7, check_double_fault                 // odd handler address: address error
        rlwinm  sr_and_flags, sr_and_flags, 0, 21, 19   // clear flag_group_1_active
        bfctr_likely cr_special_event_pending           // DISPATCH unless a special event is pending
        b       process_special_event

// FE03, _ExecuteRiscContext: (A7) points to a native context block.  Calls
// handler slot +0x964, which defaults to kernel service 1,
// RunAlternateContext.
//
// Reached from 1 dispatch table entry:
//     F-LINE cpID 7
fe03_execute_risc_context:
        lwz     data, 0(a7)
        mtlr    addr
        clrrwi  addr, data, 6                           // addr = data & 0xFFFFFFC0
        stb     zero, 0(addr)
        lis     data, 0x0020
        bflrl   cr_interrupt_pending
        lbz     data, 0(addr)
        b       test_byte

