// +0x700 in the state block.
ecr_offsets:
        .byte   0x18, 0x00, 0x04, 0x08, 0x0C, 0x10, 0x20, 0x24
        .byte   0x28, 0x30, 0x34, 0x38, 0x3C, 0x14, 0x2C, 0xA4
        .byte   0xB0, 0xB4, 0xB8, 0xA0, 0xBC, 0xC0, 0xC4, 0xA8
