        b       update_nzvc_zero
fe05_move_to_ecr_L2:
        lwz     data, config_flags(EmulatorStatePtr)
        rlwinm  data, data, 0, 29, 29                   // data = data[2] << 2
        cmpwi   cr7, data, 0
        beq     cr7, fe04_fe05_move_ecr_L2
        stw     a0, 0x700(addr)
        b       update_nzvc_zero
fe05_move_to_ecr_L3:
        lwz     data, config_flags(EmulatorStatePtr)
        clrlwi  data, data, 30                          // data = data & 0x00000003
        cmpwi   cr7, data, 3
        bne     cr7, fe04_fe05_move_ecr_L2
        mfcr    data
        rlwinm  a0, data, 8, 29, 31                     // a0 = data[26:24]
        b       update_nzvc_zero
fe05_move_to_ecr_L4:
        lwz     data, config_flags(EmulatorStatePtr)
        clrlwi  data, data, 30                          // data = data & 0x00000003
        cmpwi   cr7, data, 3
        bne     cr7, fe04_fe05_move_ecr_L2
        mcrf    cr7, cr1                                // cr7 = cr1
        li      base_disp, 0x4C0
        and     base_disp, base_disp, sr_and_flags
        cmpwi   cr6, base_disp, 0
