fe20_rtas_dispatch:
        mr      addr, a0
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        twi     31, EmulatorStatePtr, 6                 // unconditional trap
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// FE1F.  The table entry has loaded rtn_addr from handler
// slot +0x9DC, which defaults to kcall_mp_dispatch (kernel service 8,
// MPDispatch).  The handler is called with D0, A0, D1, A1, D2, A2, D3 and
// A3 in r0 and r3 to r9, and r3 to r6 are returned in D0, A0, D1 and A1.
//
// Reached from 1 dispatch table entry:
//     F-LINE cpID 7
fe1f_mp_dispatch:
        mtlr    rtn_addr                                // the handler's address
        mr      zero, d0
        mr      addr, a0
        mr      data, d1
        mr      rtn_addr, a1
        mr      immed_data, d2
        mr      base_disp, a2
        mr      d0, d3                                  // r8 and r9 are D0 and D1, already copied to r0 and r4
        mr      d1, a3
        blrl                                            // call the handler
        mr      d0, addr
        mr      a0, data
        mr      d1, rtn_addr
        mr      a1, immed_data
        li      zero, 0                                 // r0 is the emulator's zero register again
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        b       process_special_event

// Fill in the emulator state block: constants, the table of replaceable
// handler addresses (copied from handler_defaults with code_ptr added),
// and the recompiler's entry points, which start out as stubs.
init_state:
        crclr   cr_dr_enabled
        crclr   cr_dr_ready
        crclr   cr_dr_active
        crclr   cr_dr_busy
        oris    data, zero, 0x0000
        ori     data, data, 0x21F8
        stw     data, emulator_version(EmulatorStatePtr)
        oris    data, zero, 0x0000
        ori     data, data, 0x0E00
        stw     data, toolbox_trap_table(EmulatorStatePtr)
        oris    data, zero, 0x0000
        ori     data, data, 0x0400
        stw     data, os_trap_table(EmulatorStatePtr)
        stw     zero, expected_aline_vector(EmulatorStatePtr)
        stw     zero, os_trap_exit(EmulatorStatePtr)
        stw     zero, os_trap_exit_no_a0(EmulatorStatePtr)
        stw     zero, expected_privilege_vector(EmulatorStatePtr)
        lis     data, 0x8000
        ori     data, data, 0x0029
        ori     data, data, 0x0010
        stw     data, config_flags(EmulatorStatePtr)
        addis   data, code_ptr, 1                       // dr_code_base = cb + 0x10000
        stw     data, dr_code_base(EmulatorStatePtr)
        mtcrf   0x40, zero                              // cr1 = zero[27:24]
        rlwimi  sr_and_flags, zero, 0, 0, 15            // sr_and_flags[31:16] = zero[31:16]
        rlwimi  sr_and_flags, zero, 0, 21, 21           // sr_and_flags[10] = zero[10]
        stw     zero, 0x730(EmulatorStatePtr)
        stw     zero, 0x734(EmulatorStatePtr)
        stw     zero, instruction_count(EmulatorStatePtr)
        stw     zero, opcode_counts(EmulatorStatePtr)
        ori     rtn_addr, code_ptr, handler_defaults - cb - 2  // handler_defaults - 2, for the pre-incrementing loop below
        addi    addr, EmulatorStatePtr, 0x7FC
        li      data, 151                               // 151 entries
        mtctr   data
init_state_L1:
        lhzu    data, 2(rtn_addr)
        or      data, data, code_ptr                    // offsets become addresses
        stwu    data, 4(addr)
        bdnz    init_state_L1                           // CTR -= 1; branch while CTR != 0
        lwz     data, dr_code_base(EmulatorStatePtr)
        ori     addr, data, dr_setup - dr_cb
        stw     addr, dr_setup_vector(EmulatorStatePtr)
        ori     addr, data, dr_null_hook - dr_cb
        stw     addr, 0xA18(EmulatorStatePtr)
        b       handler_defaults_L1

