        stw     rtn_addr, 0x1FC(addr)
        stw     immed_data, 0x114(addr)
        stw     data, 252(addr)
        stw     pc, 60(rtn_addr)
        stw     zero, 64(rtn_addr)
switch_to_native_L1:
        stw     d0, 0(rtn_addr)
        stw     d1, 4(rtn_addr)
        stw     d2, 8(rtn_addr)
        stw     d3, 12(rtn_addr)
        stw     d4, 16(rtn_addr)
        stw     d5, 20(rtn_addr)
        stw     d6, 24(rtn_addr)
        stw     d7, 28(rtn_addr)
        stw     a0, 32(rtn_addr)
        stw     a1, 36(rtn_addr)
        stw     a2, 40(rtn_addr)
        stw     a3, 44(rtn_addr)
        stw     a4, 48(rtn_addr)
        stw     a5, 52(rtn_addr)
        stw     a6, 56(rtn_addr)
        stw     a7, 0x10C(addr)
        stb     zero, 0(addr)
        lis     data, 0x0020
        bfl     cr_interrupt_pending, kcall_run_alternate_context
        lwz     a7, 0x10C(addr)
        lwz     addr, native_context(EmulatorStatePtr)
        lbz     immed_data, 0(addr)
        lwz     d0, 0(rtn_addr)
        lwz     d1, 4(rtn_addr)
        lwz     d2, 8(rtn_addr)
        lwz     d3, 12(rtn_addr)
        lwz     d4, 16(rtn_addr)
        lwz     d5, 20(rtn_addr)
        lwz     d6, 24(rtn_addr)
        lwz     d7, 28(rtn_addr)
        cmpwi   cr5, immed_data, 255
        lwz     a0, 32(rtn_addr)
        lwz     a1, 36(rtn_addr)
        lwz     a2, 40(rtn_addr)
        lwz     a3, 44(rtn_addr)
        lwz     a4, 48(rtn_addr)
        lwz     a5, 52(rtn_addr)
        lwz     a6, 56(rtn_addr)
        lwz     data, 64(rtn_addr)
        bne     cr5, switch_to_native_L2
        lwz     pc, 60(rtn_addr)
        rlwinm  sr_and_flags, sr_and_flags, 0, 21, 19   // sr_and_flags = sr_and_flags & 0xFFFFF7FF
        cror    cr_interrupt_pending, cr_interrupt_pending, cr_special_event_pending  // cr_interrupt_pending = cr_interrupt_pending | cr_special_event_pending
        lha     prefetch_data, 0(pc)
        b       move_w_mem_ccr
switch_to_native_L2:
        addi    base_disp, immed_data, -240
        addi    pc, pc, -2
        cmplwi  cr5, base_disp, 0x0007
        stw     pc, trace_pc(EmulatorStatePtr)
        blel    cr5, switch_to_native_L3
        cmpwi   cr4, immed_data, 0
        crandc  4*cr7+eq, cr_interrupt_pending, 4*cr7+so  // cr7.eq = cr_interrupt_pending & ~cr7.so
        cror    4*cr7+eq, 4*cr7+eq, cr_special_event_pending  // cr7.eq = cr7.eq | cr_special_event_pending
        lwz     pc, 60(rtn_addr)
        crorc   4*cr7+eq, 4*cr7+eq, 4*cr4+eq            // cr7.eq = cr7.eq | ~cr4.eq
        clrlwi  data, data, 27                          // data = data & 0x0000001F
        mfcr    addr
        rlwimi  addr, sr_and_flags, 0, 20, 23           // addr[11:8] = sr_and_flags[11:8]
        addi    a7, a7, -0x100
        beql    cr7, switch_to_native_L4
        addi    a7, a7, 0x100
        rlwimi  sr_and_flags, addr, 0, 20, 23           // sr_and_flags[11:8] = addr[11:8]
        mtcrf   0x0F, addr                              // cr4..cr7 = addr[15:0]
        clrlwi  data, data, 27                          // data = data & 0x0000001F
