        b       take_fline

// Reached from 8 dispatch table entries:
//     F-LINE FRESTORE,(d16,An)
fline_mem_25:
        lwz     rtn_addr, 0x924(EmulatorStatePtr)
        b       take_fline

// Reached from 8 dispatch table entries:
//     F-LINE FRESTORE,(d8,An,Xn)
fline_mem_26:
        lwz     rtn_addr, 0x928(EmulatorStatePtr)
        b       take_fline

// Reached from 1 dispatch table entry:
//     F-LINE FRESTORE,(xxx).W
fline_mem_27:
        lwz     rtn_addr, 0x92C(EmulatorStatePtr)
        b       take_fline

// Reached from 1 dispatch table entry:
//     F-LINE FRESTORE,(xxx).L
fline_mem_28:
        lwz     rtn_addr, 0x930(EmulatorStatePtr)
        b       take_fline

// Reached from 1 dispatch table entry:
//     F-LINE FRESTORE,(d16,PC)
fline_mem_29:
        lwz     rtn_addr, 0x934(EmulatorStatePtr)
        b       take_fline

// Reached from 1 dispatch table entry:
//     F-LINE FRESTORE,(d8,PC,Xn)
fline_mem_30:
        lwz     rtn_addr, 0x938(EmulatorStatePtr)
        b       take_fline

// RTE from a format 4 frame (installed in the RTE handler table by
// install_exception_stubs): discard the two extra long words and carry
// on as for format 0.
rte_format_4:
        addi    a7, a7, 8
        b       rte_format_0

// The handlers for the forty slots.  Each works out the operand's
// effective address in addr (0 when there is none) and the instruction's
// address in rtn_addr, and moves pc past the instruction's extension
// words, according to the kind of opcode and addressing mode its slot
// stands for; the last four groups are the privileged FSAVE and FRESTORE.
fpu_stubs:
        li      addr, 0
        addi    rtn_addr, pc, -2
        addi    pc, pc, 2
        b       fpu_format_4_exception
fpu_stubs_L1:
        mtctr   addr
        ori     rtn_addr, code_ptr, fpu_stubs_L11 - cb
        li      data, 0
        bctr
fpu_stubs_L2:
        addi    addr, pc, 2
fpu_stubs_L3:
        lha     prefetch_data, 2(pc)
        addi    rtn_addr, pc, -2
        add     addr, addr, prefetch_data
        addi    pc, pc, 4
        b       fpu_format_4_exception
fpu_stubs_L4:
        li      addr, 0
        addi    rtn_addr, pc, -2
        addi    pc, pc, 6
        b       fpu_format_4_exception
fpu_stubs_L5:
        li      addr, 0
        addi    rtn_addr, pc, -2
        addi    pc, pc, 4
        b       fpu_format_4_exception
fpu_stubs_L6:
        add     addr, pc, prefetch_data
        addi    rtn_addr, pc, -2
        addi    pc, pc, 2
        b       fpu_format_4_exception
fpu_stubs_L7:
        lwz     addr, 0(pc)
        addi    rtn_addr, pc, -2
        add     addr, pc, addr
        addi    pc, pc, 4
        b       fpu_format_4_exception
fpu_stubs_L8:
        mtctr   addr
        li      data, 0
        bctrl
        mr      addr, base_disp
fpu_stubs_L9:
        bfl     cr_supervisor, take_privilege_violation
        addi    rtn_addr, pc, -2
        b       fpu_format_4_exception
fpu_stubs_L10:
        bfl     cr_supervisor, take_privilege_violation
fpu_stubs_L11:
        addi    rtn_addr, pc, -2
        addi    pc, pc, 2
        b       fpu_format_4_exception
fpu_stubs_L12:
        bfl     cr_supervisor, take_privilege_violation
fpu_stubs_L13:
        mtctr   addr
        addi    data, pc, -2
        ori     rtn_addr, code_ptr, fpu_stubs_L14 - cb
        bctr
fpu_stubs_L14:
        mr      rtn_addr, data

// Take the line-F exception with a format 4 frame.  take_exception_pc_set
// comes back here for the two extra long words before it pushes the rest.
fpu_format_4_exception:
        crset   4*cr7+so
        rlwinm  data, sr_and_flags, 8, 16, 23           // data = sr_and_flags[7:0] << 8
        li      immed_data, 0x402C                      // format 4, vector offset 0x2C
        rlwinm  sr_and_flags, sr_and_flags, 0, 26, 22   // sr_and_flags = sr_and_flags & 0xFFFFFE3F
        bl      take_exception_pc_set
        stwu    addr, -8(a7)                            // the effective address ...
        stw     rtn_addr, 4(a7)                         // ... and the address of the instruction
        blr

// Copy the second handler table (exception_stub_defaults) into the state
// block at +0x89C, and make rte_format_4 the RTE handler for format 4:
// from now on FPU opcodes produce format 4 frames (see fpu_stubs).  This
// routine is itself the default of handler slot +0x898.
install_exception_stubs:
        ori     data, code_ptr, rte_format_4 - cb
        stw     data, 0x840(EmulatorStatePtr)
        ori     rtn_addr, code_ptr, exception_stub_defaults - cb - 2
        addi    addr, EmulatorStatePtr, 0x898
        li      data, 40
        mtctr   data
install_exception_stubs_L1:
        lhzu    data, 2(rtn_addr)
        or      data, data, code_ptr
        stwu    data, 4(addr)
        bdnz    install_exception_stubs_L1              // CTR -= 1; branch while CTR != 0
        b       fetch

exception_stub_defaults:
        .short  fpu_stubs - cb
        .short  take_exception - cb
        .short  fpu_stubs_L11 - cb
        .short  fpu_stubs_L1 - cb
        .short  fpu_stubs_L1 - cb
        .short  fpu_stubs_L3 - cb
        .short  fpu_stubs_L13 - cb
        .short  fpu_stubs_L3 - cb
        .short  fpu_stubs_L13 - cb
        .short  fpu_stubs_L3 - cb
        .short  fpu_stubs_L13 - cb
        .short  take_exception - cb
        .short  fpu_stubs - cb
        .short  fpu_stubs_L2 - cb
        .short  fpu_stubs_L11 - cb
        .short  fpu_stubs_L1 - cb
        .short  fpu_stubs_L1 - cb
        .short  fpu_stubs_L3 - cb
        .short  fpu_stubs_L13 - cb
        .short  fpu_stubs_L3 - cb
        .short  fpu_stubs_L13 - cb
        .short  fpu_stubs_L5 - cb
        .short  fpu_stubs_L4 - cb
        .short  fpu_stubs - cb
        .short  fpu_stubs_L6 - cb
        .short  fpu_stubs_L7 - cb
        .short  fpu_stubs_L9 - cb
        .short  fpu_stubs_L8 - cb
        .short  fpu_stubs_L10 - cb
        .short  fpu_stubs_L12 - cb
        .short  fpu_stubs_L10 - cb
        .short  fpu_stubs_L12 - cb
        .short  fpu_stubs_L9 - cb
        .short  fpu_stubs_L8 - cb
        .short  fpu_stubs_L10 - cb
        .short  fpu_stubs_L12 - cb
        .short  fpu_stubs_L10 - cb
        .short  fpu_stubs_L12 - cb
        .short  fpu_stubs_L10 - cb
        .short  fpu_stubs_L12 - cb

// Store the complete 68K register state in the state block and return to
// the native code that called EmEntry.
exit_emulator:
        stw     d0, saved_d0(EmulatorStatePtr)
        stw     d1, 4(EmulatorStatePtr)
        stw     d2, 8(EmulatorStatePtr)
        stw     d3, 12(EmulatorStatePtr)
        stw     d4, 16(EmulatorStatePtr)
        stw     d5, 20(EmulatorStatePtr)
        stw     d6, 24(EmulatorStatePtr)
        stw     d7, 28(EmulatorStatePtr)
        stw     a0, saved_a0(EmulatorStatePtr)
        stw     a1, 36(EmulatorStatePtr)
        stw     a2, 40(EmulatorStatePtr)
        stw     a3, 44(EmulatorStatePtr)
        stw     a4, 48(EmulatorStatePtr)
        stw     a5, 52(EmulatorStatePtr)
        stw     a6, 56(EmulatorStatePtr)
        stw     a7, saved_a7(EmulatorStatePtr)
        addi    pc, pc, -2                              // pc of the next instruction
        stw     pc, saved_pc(EmulatorStatePtr)
        rlwinm  data, sr_and_flags, 8, 16, 23           // rebuild the full SR: system byte ...
        rlwimi  data, ccr_x, 7, 27, 27                  // ... X
        mfcr    ccr_x
        rlwimi  data, ccr_x, 4, 28, 28                  // ... N
        rlwimi  data, ccr_x, 5, 29, 29                  // ... Z
        mfxer   ccr_x                                   // X = C (ccr_x keeps a copy of XER)
        rlwimi  data, ccr_x, 3, 30, 31                  // ... V and C
        sth     data, saved_sr(EmulatorStatePtr)
        lwz     r1, native_sp(EmulatorStatePtr)         // back onto the caller's stack
        lmw     r11, 0(r1)                              // restore r11..r31
        mtcr    r11                                     // CR = r11
        mtlr    r12
        addic   r1, r1, 84
        blr

// ===========================================================================
// Emulator entry point
// ===========================================================================
// Called once by native code with r3 = address of the emulator state
// block and r4 = address of the dispatch table (OpcodeTblTop).
// Saves the caller's non-volatile registers in a frame at the top of the
// state block's page, records where the code and the table are, fills in
// the emulator's context block (flags, the handler for native exceptions
// and its argument, and emulator_reset as the place to resume), and
// issues kernel trap 0, ReturnFromException.  The kernel resumes the
// context at ecb_pc, which is how emulator_reset is reached.
EmEntry:
        addi    r1, r3, 0x1000                          // r1 = top of the 4 KB page that starts at the state block
        bl      em_entry_save
        twi     31, r0, -0x2153                         // not reached (the operand is 0xDEAD)
EmEntry_L1:
        b       EmEntry_L1

// Kernel service calls.  Each is an unconditional trap instruction.  The
// kernel recognises a trap taken inside this table by its address - slot
// n is service n - and resumes at the following instruction, so callers
// reach these with a branch-and-link, or with a plain branch when LR
// already holds the return address.  (It also recognises the instruction
// "twi 31, r31, n" anywhere else, by its operand.)
//
// The service names are those of the NanoKernel disassembly in the
// powermac-rom project.  Slot 14 carries the operand 13, which is harmless
// because the slot's address decides; slot 16 is beyond the kernel's
// sixteen services.
EmKernelTrapTable:
        twi     31, EmulatorStatePtr, 0                 // 0: ReturnFromException - resume this context at ecb_pc

kcall_run_alternate_context:
        twi     31, EmulatorStatePtr, 1                 // 1: RunAlternateContext - run native code

kcall_reset_system:
        twi     31, EmulatorStatePtr, 2                 // 2: ResetSystem

kcall_vm_dispatch:
        twi     31, EmulatorStatePtr, 3                 // 3: VMDispatch

kcall_prioritize_interrupts:
        twi     31, EmulatorStatePtr, 4                 // 4: PrioritizeInterrupts

kcall_power_dispatch:
        twi     31, EmulatorStatePtr, 5                 // 5: PowerDispatch
        twi     31, EmulatorStatePtr, 6                 // 6: RTASDispatch

kcall_cache_dispatch:
        twi     31, EmulatorStatePtr, 7                 // 7: CacheDispatch

kcall_mp_dispatch:
        twi     31, EmulatorStatePtr, 8                 // 8: MPDispatch
        twi     31, EmulatorStatePtr, 9                 // 9
        twi     31, EmulatorStatePtr, 10                // 10
        twi     31, EmulatorStatePtr, 11                // 11
        twi     31, EmulatorStatePtr, 12                // 12
        twi     31, EmulatorStatePtr, 13                // 13
        twi     31, EmulatorStatePtr, 13                // 14 (operand 13)

kcall_thud:
        twi     31, EmulatorStatePtr, 15                // 15: Thud (kernel panic)
        twi     31, EmulatorStatePtr, 16                // 16

em_entry_save:
        mfcr    r11                                     // save CR ...
        stwu    r11, -84(r1)
        mflr    r12                                     // ... LR ...
        stmw    r12, 4(r1)                              // ... and r12..r31 below the top of the page
        mr      EmulatorStatePtr, r3                    // r3: the state block
        mr      disp_table, r4                          // r4: the dispatch table
        stw     disp_table, saved_disp_table(EmulatorStatePtr)
        mflr    code_ptr                                // code_ptr = this code's own address, rounded down to 64 KB
        clrrwi  code_ptr, code_ptr, 16                  // code_ptr = code_ptr & 0xFFFF0000
        stw     code_ptr, saved_code_ptr(EmulatorStatePtr)
        stw     addr, ecb_r3(EmulatorStatePtr)
        stw     data, ecb_r4(EmulatorStatePtr)
        ori     r0, code_ptr, emulator_reset - cb       // where ReturnFromException will resume
        stw     r0, ecb_pc(EmulatorStatePtr)
        li      r0, 7
        stw     r0, ecb_saved_flags(EmulatorStatePtr)
        li      r0, -1
        stw     r0, ecb_saved_enables(EmulatorStatePtr)
        ori     r0, code_ptr, native_exception_handler - cb  // handler for native exceptions taken while emulating
        stw     r0, ecb_handler(EmulatorStatePtr)
        ori     r0, code_ptr, take_bus_error - cb       // its argument: where to resume for a bus error
        stw     r0, ecb_handler_arg(EmulatorStatePtr)
        li      addr, 0
        b       EmKernelTrapTable                       // ReturnFromException: resume at ecb_pc

// The emulator context starts here: clear the 68K registers, initialise
// the state block, then do what a 68K does on reset - load the stack
// pointer from address 0 and the pc from address 4, enter supervisor
// state with interrupts masked - and dispatch the first instruction.
emulator_reset:
        li      zero, 0
        li      dr_entry, 0
        mtcrf   0x7F, zero                              // cr1..cr7 = zero[27:0]
        bl      init_state
        li      d0, 0
        li      d1, 0
        li      d2, 0
        li      d3, 0
        li      d4, 0
        li      d5, 0
        li      d6, 0
        li      d7, 0
        li      a0, 0
        li      a1, 0
        li      a2, 0
        li      a3, 0
        li      a4, 0
        li      a5, 0
        li      a6, 0
        li      pc, 0
        lwz     a7, 0(pc)                               // initial SSP from the reset vector
        lwz     pc, 4(pc)                               // initial PC
        li      vbr, 0
        stw     vbr, saved_vbr(EmulatorStatePtr)
        li      sr_and_flags, 39                        // SR = $27xx: supervisor, interrupt mask 7
        crset   cr_supervisor
        li      ccr_x, 0
        mtcrf   0x80, zero                              // N = Z = 0
        mtxer   zero                                    // V = C = 0
        lha     prefetch_data, 0(pc)
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        lhau    prefetch_data, 2(pc)                    // PREFETCH: pc += 2, load the word there
        bctr
        .long   0x48000014
        ALIGN(64)

interpreter_credits:
        .ascii  "680x0 Emulation written by Gary Davidian"
        .space  4

// Fixed-position branch into the recompiler's code block.
dr_translate_stub:
        b       dr_translate_stub_2
        ALIGN(64)

dr_translate_stub_2:
        b       dr_translate
        ALIGN(0x10000)
